export const POETS = [{"id": 1, "name": "陶渊明", "zi": "元亮", "hao": "五柳先生", "dynasty": "魏晋", "years": "约365-427", "title": "田园诗祖", "intro": "东晋诗人。曾任彭泽县令，八十余日即辞官归隐，此后躬耕田园二十余年。开创田园诗派，\"采菊东篱下\"成为中国人心中隐逸生活的代名词。", "story": "义熙元年冬，彭泽县衙来了新县令。恰逢郡里督邮来视察，属吏提醒他束带迎接。陶渊明叹了口气：\"吾不能为五斗米折腰，拳拳事乡里小人邪！\"当天解下印绶，回家写了那篇著名的《归去来兮辞》。\n此后二十余年，他真的种地、酿酒、写诗。地里种秫谷专供酿酒，朋友颜延之留下二万钱，他全数送到酒家，日后陆续去取酒喝。\n穷到什么地步？《乞食》里写自己饿得出门讨饭，主人端出酒菜，他不知如何答谢，索性写诗相赠。可就是这个讨饭的人，替此后一千多年的中国文人守住了一片\"心远地自偏\"的精神田园。", "storyTitle": "不为五斗米折腰", "journey": "[{\"place\": \"浔阳柴桑\", \"modern\": \"江西九江西南\", \"lon\": 115.89, \"lat\": 29.62, \"period\": \"365—393 · 少年耕读\", \"event\": \"出身没落仕宦之家，少怀「猛志逸四海」；几度出仕，皆因亲老家贫、口腹自役。\", \"poems\": []}, {\"place\": \"江陵\", \"modern\": \"湖北荆州\", \"lon\": 112.19, \"lat\": 30.33, \"period\": \"398—401 · 幕府生涯\", \"event\": \"入桓玄幕府，看尽门阀倾轧、宦海浮沉，归意渐生。\", \"poems\": []}, {\"place\": \"彭泽\", \"modern\": \"江西彭泽\", \"lon\": 116.55, \"lat\": 29.9, \"period\": \"405 · 八十余日\", \"event\": \"为彭泽令，郡遣督邮至，吏白应束带见之；叹曰「吾不能为五斗米折腰，拳拳事乡里小人邪」，即日解印绶去职，赋《归去来兮辞》。\", \"poems\": []}, {\"place\": \"柴桑 · 归隐\", \"modern\": \"江西九江\", \"lon\": 115.92, \"lat\": 29.58, \"period\": \"405—427 · 采菊东篱\", \"event\": \"躬耕南山，把酒东篱，与庐山高僧往还，隐居终老。结庐人境，心远地偏，悠然见山。\", \"poems\": [1, 2]}]"}, {"id": 2, "name": "李白", "zi": "太白", "hao": "青莲居士", "dynasty": "唐", "years": "701-762", "title": "诗仙", "intro": "唐代伟大的浪漫主义诗人，诗风豪放飘逸、想象瑰奇。一生漫游天下，剑术、诗文、酒量皆名动一时。存诗近千首。", "story": "天宝元年，李白奉诏入京，玄宗\"降辇步迎，以七宝床赐食，御手调羹\"。可他很快发现，皇帝要的只是一个点缀升平的词臣，不是经世济民的谋士。\n于是他纵酒狂歌。传说醉中奉诏草诏，竟伸脚让高力士脱靴，让贵妃捧砚。谤谤由此而起，不到两年，玄宗\"赐金放还\"——体面地请走了他。\n离开长安那年，他在灞桥写下\"行路难\"；可转身又说\"长风破浪会有时\"。这就是李白：仕途从未顺遂，笔下从未低头。杜甫形容他\"笔落惊风雨，诗成泣鬼神\"，一千多年后，我们抬头看月亮，仍会想起他的床前霜。", "storyTitle": "仰天大笑出门去", "journey": "[{\"place\": \"绵州 · 青莲乡\", \"modern\": \"四川江油\", \"lon\": 104.75, \"lat\": 31.77, \"period\": \"701—724 · 蜀中\", \"event\": \"五岁诵六甲，十岁观百家；十五好剑术，二十五「仗剑去国，辞亲远游」。\", \"poems\": []}, {\"place\": \"扬州\", \"modern\": \"江苏扬州\", \"lon\": 119.42, \"lat\": 32.39, \"period\": \"726 · 二十六岁\", \"event\": \"漫游吴会，秋病卧扬州旅舍，客夜霜白，举头见月而成《静夜思》。\", \"poems\": [3]}, {\"place\": \"安陆\", \"modern\": \"湖北安陆\", \"lon\": 113.69, \"lat\": 31.26, \"period\": \"727—736\", \"event\": \"娶故相许圉师孙女，「酒隐安陆，蹉跎十年」。\", \"poems\": []}, {\"place\": \"长安\", \"modern\": \"陕西西安\", \"lon\": 108.94, \"lat\": 34.27, \"period\": \"742—744 · 翰林供奉\", \"event\": \"奉诏入京，供奉翰林；醉草诏书、力士脱靴，终为权贵所谗，赐金放还。花间一壶酒，对影成三人。\", \"poems\": [5]}, {\"place\": \"宣城\", \"modern\": \"安徽宣城\", \"lon\": 118.76, \"lat\": 30.95, \"period\": \"753—761 · 往来宣城\", \"event\": \"晚年屡游宣城，相看两不厌，只有敬亭山。\", \"poems\": []}, {\"place\": \"庐山\", \"modern\": \"江西庐山\", \"lon\": 115.98, \"lat\": 29.56, \"period\": \"756 · 屏风叠\", \"event\": \"初游庐山有「飞流直下三千尺」；是岁隐屏风叠，永王璘三聘入幕，由此罹祸。\", \"poems\": [4]}, {\"place\": \"白帝城\", \"modern\": \"重庆奉节\", \"lon\": 109.58, \"lat\": 31.04, \"period\": \"759 · 流放遇赦\", \"event\": \"坐永王案长流夜郎，溯江而上，行至白帝城遇赦——朝辞彩云间，千里江陵一日还。\", \"poems\": [6]}, {\"place\": \"当涂\", \"modern\": \"安徽当涂\", \"lon\": 118.5, \"lat\": 31.57, \"period\": \"762\", \"event\": \"投族叔当涂令李阳冰，枕上授简；病殁，传说醉中入水捉月骑鲸而去。\", \"poems\": []}]"}, {"id": 3, "name": "王维", "zi": "摩诘", "hao": "摩诘居士", "dynasty": "唐", "years": "约701-761", "title": "诗佛", "intro": "唐代山水田园诗代表，兼通音律、书画。苏轼评其\"诗中有画，画中有诗\"。晚年半官半隐于辋川，写下一系列空灵澄澈的山水绝唱。", "story": "王维的人生在四十岁那年劈成两半。前半生是少年得意：二十一岁进士及第，一曲《郁轮袍》名动公卿，状元及第，仕途坦荡。\n安史之乱中，他被叛军俘获，被迫任伪职。乱平后，凡受伪职者论罪，他因写过哀痛的《凝碧池》诗、且弟王缙请削己职为兄赎罪，方得免究。\n从此他\"晚年唯好静，万事不关心\"，半官半隐于辋川别业，与裴迪泛舟唱和，写《鹿柴》，写《山居秋暝》。水墨从此替代了颜色，\"空山\"替代了庙堂。他在诗里活成了自己的桃花源。", "storyTitle": "诗中有画，画中有诗", "journey": "[{\"place\": \"蒲州\", \"modern\": \"山西永济\", \"lon\": 110.28, \"lat\": 34.85, \"period\": \"701—715\", \"event\": \"祖籍太原祁县，父迁蒲州；少年聪颖，通音律、善书画。\", \"poems\": []}, {\"place\": \"长安\", \"modern\": \"陕西西安\", \"lon\": 108.94, \"lat\": 34.27, \"period\": \"715—737 · 两京游历\", \"event\": \"十七岁独在异乡，重阳忆蒲州兄弟；二十一进士夺魁，为太乐丞，仕途几起几落。\", \"poems\": [9, 10]}, {\"place\": \"凉州\", \"modern\": \"甘肃武威\", \"lon\": 102.64, \"lat\": 37.93, \"period\": \"737 · 出塞\", \"event\": \"以监察御史出塞宣慰河西，大漠孤烟直，长河落日圆，诗境为之一阔。\", \"poems\": []}, {\"place\": \"辋川\", \"modern\": \"陕西蓝田\", \"lon\": 108.92, \"lat\": 34.09, \"period\": \"741—761 · 半官半隐\", \"event\": \"得宋之问蓝田别墅，与裴迪泛舟唱和，弹琴赋诗；安史乱后笃志奉佛，晚官尚书右丞，空山新雨、竹喧莲动皆成绝唱。\", \"poems\": [7, 8]}]"}, {"id": 4, "name": "杜甫", "zi": "子美", "hao": "少陵野老", "dynasty": "唐", "years": "712-770", "title": "诗圣", "intro": "唐代现实主义诗人。历经安史之乱，诗风沉郁顿挫，深刻记录了时代苦难，其诗被后世称为\"诗史\"。与李白并称\"李杜\"。", "story": "杜甫的后半生，几乎就是一部安史之乱的编年史。\n长安十年求官，他写\"朝扣富儿门，暮随肥马尘\"。乱起，他被困在沦陷的长安，写下\"国破山河在，城春草木深\"。逃至凤翔见肃宗，得授左拾遗，又因营救房琯被贬。\n弃官入蜀，成都浣花溪畔的草堂是他难得的安稳岁月，\"两个黄鹂鸣翠柳\"就写于此时。好友严武去世，他失去依靠，携家漂泊夔州、湖湘。\n大历五年冬，五十九岁的杜甫病逝于湘江一条小舟上。临终前，他惦记的仍是\"战血流依旧，军声动至今\"。他一生没有过上几天好日子，却始终替苍生写诗。", "storyTitle": "诗史：用一生记录一个时代", "journey": "[{\"place\": \"洛阳 · 巩县\", \"modern\": \"河南巩义\", \"lon\": 113.02, \"lat\": 34.75, \"period\": \"712—735\", \"event\": \"生于巩县瑶湾，七龄思即壮，开口咏凤凰。\", \"poems\": []}, {\"place\": \"长安\", \"modern\": \"陕西西安\", \"lon\": 108.94, \"lat\": 34.27, \"period\": \"746—755 · 困守十年\", \"event\": \"应诏就试，朝扣富儿门，暮随肥马尘；安史乱起身陷长安，国破山河在，感时花溅泪。\", \"poems\": [11]}, {\"place\": \"秦州\", \"modern\": \"甘肃天水\", \"lon\": 105.72, \"lat\": 34.58, \"period\": \"759 · 弃官西行\", \"event\": \"弃官携家流寓秦州，露从今夜白，月是故乡明。\", \"poems\": [13]}, {\"place\": \"成都\", \"modern\": \"四川成都\", \"lon\": 104.07, \"lat\": 30.67, \"period\": \"760—765 · 草堂\", \"event\": \"得故人严武相助，浣花溪畔筑草堂，暂得安顿；好雨知时节，随风潜入夜。\", \"poems\": [12]}, {\"place\": \"夔州\", \"modern\": \"重庆奉节\", \"lon\": 109.46, \"lat\": 31.02, \"period\": \"766—768\", \"event\": \"寓夔州两年，登白帝高台，无边落木萧萧下，不尽长江滚滚来。\", \"poems\": [14]}, {\"place\": \"岳阳\", \"modern\": \"湖南岳阳\", \"lon\": 113.09, \"lat\": 29.36, \"period\": \"768—770\", \"event\": \"漂泊湖湘，亲朋无一字，老病有孤舟；卒于潭岳间湘江舟中。\", \"poems\": []}]"}, {"id": 5, "name": "白居易", "zi": "乐天", "hao": "香山居士", "dynasty": "唐", "years": "772-846", "title": "诗魔", "intro": "中唐诗人，倡导新乐府运动，主张\"文章合为时而著，歌诗合为事而作\"。《长恨歌》《琵琶行》为千古绝唱。诗风浅切平易，流传极广。", "story": "白居易写诗有个执念：让不识字的老太太也能听懂。据说每写完一首，先念给老婆婆听，\"问曰：解否？\"解则录之，不解则改。这便是\"老妪能解\"的典故。\n他确实做到了。《长恨歌》问世后传诵天下，歌女会背便自抬身价：\"我诵得白学士《长恨歌》，岂同他妓哉！\"连皇帝都感慨：童子解吟长恨曲，胡儿能唱琵琶篇。\n元和十年被贬江州司马，浔阳江头夜遇琵琶女，写\"同是天涯沦落人，相逢何必曾相识\"。晚年居洛阳香山，自号香山居士，与刘禹锡诗酒唱和，活成了唐代诗人里少有的长寿与通达。", "storyTitle": "老妪能解", "journey": "[{\"place\": \"新郑\", \"modern\": \"河南新郑\", \"lon\": 113.74, \"lat\": 34.4, \"period\": \"772—780\", \"event\": \"生于新郑东郭宅，兵乱早年随家迁避。\", \"poems\": []}, {\"place\": \"符离\", \"modern\": \"安徽宿州\", \"lon\": 117.32, \"lat\": 33.66, \"period\": \"782—799\", \"event\": \"避地符离，苦节读书——口舌成疮，手肘成胝。\", \"poems\": []}, {\"place\": \"长安\", \"modern\": \"陕西西安\", \"lon\": 108.94, \"lat\": 34.27, \"period\": \"787 · 行卷\", \"event\": \"十六岁以《赋得古原草送别》投谒顾况；况戏曰「长安米贵，居大不易」，及读「野火烧不尽」，叹曰「有句如此，居天下有甚难」。\", \"poems\": [15]}, {\"place\": \"江州\", \"modern\": \"江西九江\", \"lon\": 115.99, \"lat\": 29.71, \"period\": \"815—818 · 贬谪\", \"event\": \"武元衡案贬江州司马，浔阳江头夜送客，忽闻水上琵琶声——江州司马青衫湿。\", \"poems\": []}, {\"place\": \"杭州\", \"modern\": \"浙江杭州\", \"lon\": 120.16, \"lat\": 30.25, \"period\": \"822—824 · 刺杭州\", \"event\": \"赴杭道上吟「半江瑟瑟半江红」；守杭浚六井、筑堤蓄湖，最爱湖东行不足，绿杨阴里白沙堤。\", \"poems\": [16, 17]}, {\"place\": \"洛阳\", \"modern\": \"河南洛阳\", \"lon\": 112.45, \"lat\": 34.62, \"period\": \"829—846\", \"event\": \"晚居履道里，自号香山居士，与刘禹锡诗酒唱和，卒葬龙门香山。\", \"poems\": []}]"}, {"id": 6, "name": "苏轼", "zi": "子瞻", "hao": "东坡居士", "dynasty": "宋", "years": "1037-1101", "title": "坡仙", "intro": "北宋文学家、书画家，豪放词开创者。诗、词、文、书、画皆臻一流，\"唐宋八大家\"之一。一生三起三落，愈贬愈旷达。", "story": "元丰二年，御史摘录苏轼诗文弹劾他讥讽朝政，他被押赴御史台狱一百三十天，几死于狱中——史称\"乌台诗案\"。出狱后贬为黄州团练副使，不得签书公事。\n俸禄断绝，他在城东坡地开荒种麦，自号\"东坡居士\"。就是在黄州，他写了《念奴娇·赤壁怀古》和前后《赤壁赋》，也写了被贬的豁达：\"竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。\"\n此后他一贬再贬：惠州，\"日啖荔枝三百颗\"；儋州，垂老投荒，他却办学堂、教书育人。建中靖国元年遇赦北归，途中病逝常州。临终前，友人说此行即便无生还可能也勿哭，他答：无生还可能，也无须哭。一生大起大落，他始终把苦难过成了诗。", "storyTitle": "一蓑烟雨任平生", "journey": "[{\"place\": \"眉山\", \"modern\": \"四川眉山\", \"lon\": 103.85, \"lat\": 30.05, \"period\": \"1037—1056\", \"event\": \"眉州眉山人；程夫人授《范滂传》，慨然有澄清天下之志。\", \"poems\": []}, {\"place\": \"汴京\", \"modern\": \"河南开封\", \"lon\": 114.31, \"lat\": 34.8, \"period\": \"1057—1071\", \"event\": \"嘉祐二年进士，欧阳修见其书曰「吾当避此人出一头地」；与新党不合，自请外任。\", \"poems\": []}, {\"place\": \"杭州\", \"modern\": \"浙江杭州\", \"lon\": 120.16, \"lat\": 30.25, \"period\": \"1071—1074 通判 · 1089—1091 再知\", \"event\": \"初为杭州通判，「欲把西湖比西子，淡妆浓抹总相宜」；十八年后再知杭州，疏浚西湖、筑苏堤，三潭印月自此始。\", \"poems\": [19], \"lx\": -25, \"ly\": 30}, {\"place\": \"密州\", \"modern\": \"山东诸城\", \"lon\": 119.41, \"lat\": 35.99, \"period\": \"1074—1076 · 知州\", \"event\": \"知密州，西北望，射天狼；丙辰中秋欢饮达旦，怀子由而作水调歌头，明月几时有。\", \"poems\": [18]}, {\"place\": \"徐州\", \"modern\": \"江苏徐州\", \"lon\": 117.18, \"lat\": 34.26, \"period\": \"1077—1079\", \"event\": \"知徐州，黄河决口汇于城下，庐于城上，率军民抗洪七十余日。\", \"poems\": []}, {\"place\": \"湖州\", \"modern\": \"浙江湖州\", \"lon\": 120.09, \"lat\": 30.87, \"period\": \"1079 · 乌台诗案\", \"event\": \"知湖州三月，以诗文讪谤朝政下御史台狱，系狱百三十日，几死。\", \"poems\": [], \"ly\": 22}, {\"place\": \"黄州\", \"modern\": \"湖北黄冈\", \"lon\": 114.87, \"lat\": 30.45, \"period\": \"1080—1084 · 谪居\", \"event\": \"贬黄州团练副使，躬耕城东坡地，自号东坡居士；两赋一词，从此天下称苏东坡。\", \"poems\": []}, {\"place\": \"庐山\", \"modern\": \"江西庐山\", \"lon\": 115.98, \"lat\": 29.56, \"period\": \"1084 · 途经\", \"event\": \"量移汝州，道经庐山，横看成岭侧成峰，题诗西林寺壁。\", \"poems\": [20]}, {\"place\": \"惠州\", \"modern\": \"广东惠州\", \"lon\": 114.42, \"lat\": 23.11, \"period\": \"1094—1097\", \"event\": \"绍圣再贬惠州，日啖荔枝三百颗，不辞长作岭南人。\", \"poems\": []}, {\"place\": \"儋州\", \"modern\": \"海南儋州\", \"lon\": 109.58, \"lat\": 19.52, \"period\": \"1097—1100 · 天涯\", \"event\": \"责授琼州别驾、昌化军安置，渡海讲学明道；海南破天荒出进士，自公始。\", \"poems\": []}, {\"place\": \"常州\", \"modern\": \"江苏常州\", \"lon\": 119.95, \"lat\": 31.78, \"period\": \"1101\", \"event\": \"遇赦自海南北归，七月二十八日卒于常州；葬汝州郏城县，号小峨眉。\", \"poems\": []}]"}, {"id": 7, "name": "李清照", "zi": "", "hao": "易安居士", "dynasty": "宋", "years": "1084-约1155", "title": "千古第一才女", "intro": "宋代婉约词代表。前期词清丽明快，南渡后因国破家亡、丈夫病逝而转为沉郁凄怆。提出词\"别是一家\"之说，有《漱玉词》传世。", "story": "李清照与赵明诚的婚姻，是文学史上著名的美谈。夫妻共治金石、校书填词，饭后烹茶，指堆积书史，言某事在某书某卷第几页，以中否赌胜负——\"中即举杯大笑，至茶倾覆怀中\"。赌书泼茶，成了后世羡慕了千年的闺中雅事。\n靖康之变，金石书画在流亡中散失殆尽；建炎三年，赵明诚病逝建康。她携残册追随朝廷流寓江南，晚境孤苦，改嫁遇人不淑，宁受牢狱之灾也要讼离。\n早年她写\"兴尽晚回舟\"，晚年只剩\"寻寻觅觅，冷冷清清\"。一个人的词风，量出了一整个时代的伤口。", "storyTitle": "赌书消得泼茶香", "journey": "[{\"place\": \"济南 · 明水\", \"modern\": \"山东济南\", \"lon\": 117.12, \"lat\": 36.65, \"period\": \"1084—1101\", \"event\": \"生于齐州章丘明水，父李格非为苏门后四学士；少女时代溪亭日暮，沉醉不知归路。\", \"poems\": [21]}, {\"place\": \"汴京\", \"modern\": \"河南开封\", \"lon\": 114.31, \"lat\": 34.8, \"period\": \"1101—1127\", \"event\": \"与太学生赵明诚成婚，赌书泼茶，共撰《金石录》；书画词章，名动京师。\", \"poems\": []}, {\"place\": \"青州\", \"modern\": \"山东青州\", \"lon\": 118.48, \"lat\": 36.69, \"period\": \"1107—1127 · 归来堂\", \"event\": \"屏居青州乡里十年，易安室归来堂，节衣缩食以聚书，极文墨之乐。\", \"poems\": []}, {\"place\": \"江宁\", \"modern\": \"江苏南京\", \"lon\": 118.8, \"lat\": 32.06, \"period\": \"1128—1129\", \"event\": \"靖康之变，仓皇南渡；明诚知建康府，感怀京洛旧事，寻寻觅觅已自北地始。\", \"poems\": []}, {\"place\": \"金华\", \"modern\": \"浙江金华\", \"lon\": 119.65, \"lat\": 29.08, \"period\": \"1134\", \"event\": \"避乱金华，闻双溪春尚好——只恐双溪舴艋舟，载不动许多愁。\", \"poems\": []}, {\"place\": \"临安\", \"modern\": \"浙江杭州\", \"lon\": 120.16, \"lat\": 30.25, \"period\": \"1132—1155\", \"event\": \"流寓临安，物是人非事事休；晚境凄凉，改嫁离异、金石散尽，卒年不可考。\", \"poems\": [22]}]"}, {"id": 8, "name": "辛弃疾", "zi": "幼安", "hao": "稼轩", "dynasty": "宋", "years": "1140-1207", "title": "词中之龙", "intro": "南宋豪放词代表，与苏轼并称\"苏辛\"。生于金占区，二十一岁聚众起义，曾率五十骑夜袭金营生擒叛将。一生力主北伐而不获用，把壮志都写进了词。", "story": "辛弃疾本是武将。二十一岁在金占区聚众两千起义，归附耿京；叛徒义端窃印逃跑，他单骑追斩；后来耿京被叛徒张安国所害，他率五十骑直闯五万人的金营，生擒张安国，缚于马上，渡江献俘——那年他二十三岁。\n南归后他却再也回不了前线。朝廷忌惮其\"归正人\"身份，四十年间三度起用、屡遭弹劾，闲居带湖、瓢泉近二十年。他把金戈铁马都写进词里：\"醉里挑灯看剑，梦回吹角连营。\"\n开禧三年秋，传说病重中的辛弃疾大呼\"杀贼\"数声而逝。他终究没能马踏胡尘，却以六百余首词，成了宋词里的最后一个骑士。", "storyTitle": "醉里挑灯看剑", "journey": "[{\"place\": \"济南 · 历城\", \"modern\": \"山东济南\", \"lon\": 117.12, \"lat\": 36.65, \"period\": \"1140—1161\", \"event\": \"生于金占区，祖父辛赞携以登高望远，指画山河；二十二岁聚众二千起义，率五十骑闯五万人金营，生擒叛将张安国。\", \"poems\": []}, {\"place\": \"临安\", \"modern\": \"浙江杭州\", \"lon\": 120.16, \"lat\": 30.25, \"period\": \"1162 · 献俘南归\", \"event\": \"押张安国献俘行在，脱身南归；「归正人」三字，自此伴其一生。\", \"poems\": []}, {\"place\": \"建康\", \"modern\": \"江苏南京\", \"lon\": 118.8, \"lat\": 32.06, \"period\": \"1168—1175\", \"event\": \"通判建康、参赞军务，楚天千里清秋，登赏心亭，把吴钩看了，栏杆拍遍。\", \"poems\": []}, {\"place\": \"带湖 · 上饶\", \"modern\": \"江西上饶\", \"lon\": 117.97, \"lat\": 28.45, \"period\": \"1182—1192 · 闲居\", \"event\": \"落职闲居带湖新居，醉里挑灯看剑，梦回吹角连营；夜行黄沙道中，听取蛙声一片。\", \"poems\": [23, 24]}, {\"place\": \"瓢泉 · 铅山\", \"modern\": \"江西铅山\", \"lon\": 117.71, \"lat\": 28.32, \"period\": \"1196—1207\", \"event\": \"再迁瓢泉，起用复罢者再；开禧北伐之际朝廷欲用，病笃辞免，九月十日忧愤而卒，临终大呼「杀贼」数声。\", \"poems\": []}]"}, {"id": 9, "name": "曹操", "zi": "孟德", "hao": "", "dynasty": "魏晋", "years": "155—220", "title": "建安风骨", "intro": "汉末杰出的政治家、军事家、诗人，建安文学的开创者。「外定武功，内兴文学」，与曹丕、曹植并称三曹，慷慨悲凉，气韵沉雄。", "story": "他是乱世里真正的多面手：挟天子以令诸侯，屯田足食，扫平北方；铜雀台上横槊赋诗，把政治家的胸襟写成了诗。他对文学只以「相王之尊」提倡雅爱，却凭一己之力抬高了一个时代的声音。\n鲁迅说他「至少是一个英雄」。建安风骨的「风骨」二字，一半是他杀伐决断的棱角，一半是他诗里那声「白骨露于野，千里无鸡鸣」的悲悯。", "storyTitle": "横槊赋诗", "journey": "[\n {\"place\":\"洛阳\",\"modern\":\"河南洛阳\",\"lon\":112.45,\"lat\":34.62,\"period\":\"155—189 · 少年起家\",\"event\":\"生于沛国谯县，二十岁举孝廉入洛阳为郎，五色棒悬门，夜巡不避豪贵。\",\"poems\":[]},\n {\"place\":\"陈留 · 己吾\",\"modern\":\"河南开封\",\"lon\":114.40,\"lat\":34.65,\"period\":\"189 · 散家财起兵\",\"event\":\"董卓乱政，变易姓名间行东归，陈留起兵讨卓；行军所见「白骨露于野」，遂有蒿里之悲。\",\"poems\":[28]},\n {\"place\":\"官渡\",\"modern\":\"河南中牟\",\"lon\":113.90,\"lat\":34.72,\"period\":\"200 · 决战\",\"event\":\"以弱胜强大破袁绍，为统一北方奠定基业。\",\"poems\":[]},\n {\"place\":\"邺城\",\"modern\":\"河北临漳\",\"lon\":114.61,\"lat\":36.33,\"period\":\"204—220 · 王都\",\"event\":\"定邺为都，建铜雀台，曹氏父子与建安诸子宴饮赋诗，开一代文风。\",\"poems\":[]},\n {\"place\":\"碣石\",\"modern\":\"河北昌黎\",\"lon\":119.16,\"lat\":39.71,\"period\":\"207 · 北征乌桓\",\"event\":\"白狼山破乌桓，凯旋经碣石，东临大海——日月之行，若出其中；星汉灿烂，若出其里。\",\"poems\":[25,26]},\n {\"place\":\"赤壁\",\"modern\":\"湖北赤壁\",\"lon\":113.63,\"lat\":29.88,\"period\":\"208 · 横槊赋诗\",\"event\":\"饮马长江，横槊赋诗，「对酒当歌，人生几何」；兵败赤壁，天下遂成三分。建安二十五年还军洛阳，病逝，遗令「天下尚未安定，未得遵古」葬毕即除服。\",\"poems\":[27]}\n]"}, {"id": 10, "name": "孟浩然", "zi": "", "hao": "孟山人", "dynasty": "唐", "years": "689—740", "title": "诗隐", "intro": "盛唐山水田园诗派第一人，襄阳人。一生布衣，终身不仕，却在隐与仕之间徘徊了一辈子。诗清淡自然，语淡味终不薄。", "story": "四十岁那年他赴长安应举，据说在王维处偶遇玄宗，诵到「不才明主弃」，玄宗不悦：「卿不求仕，而朕未尝弃卿，奈何诬我！」从此断了仕途。\n他回到襄阳的涧南园与鹿门山，把失意过成了千古风流。李白说「吾爱孟夫子，风流天下闻」，杜甫也说「清诗句句尽堪传」——终身白衣，却让满朝朱紫低头。", "storyTitle": "不才明主弃", "journey": "[\n {\"place\":\"襄阳 · 涧南园\",\"modern\":\"湖北襄阳\",\"lon\":112.12,\"lat\":32.01,\"period\":\"689—727 · 隐居\",\"event\":\"家世业儒，隐居鹿门山与涧南园，春眠闻鸟，把酒话桑麻，田园诗成于此。\",\"poems\":[29,30]},\n {\"place\":\"长安\",\"modern\":\"陕西西安\",\"lon\":108.94,\"lat\":34.27,\"period\":\"727—729 · 应举不第\",\"event\":\"四十岁赴京应进士举不第，据传太乐署诵诗误触玄宗，「不才明主弃」一句断了仕途。\",\"poems\":[]},\n {\"place\":\"建德江\",\"modern\":\"浙江建德\",\"lon\":119.28,\"lat\":29.60,\"period\":\"730—733 · 吴越漫游\",\"event\":\"自洛阳东游吴越，日暮移舟烟渚，客愁新起，对江清月近人。\",\"poems\":[31]},\n {\"place\":\"洞庭湖\",\"modern\":\"湖南岳阳\",\"lon\":113.09,\"lat\":29.36,\"period\":\"733 · 干谒\",\"event\":\"八月洞庭水涨，上诗张九龄冀见援引——气蒸云梦泽，波撼岳阳城；终无所遇。\",\"poems\":[32]},\n {\"place\":\"襄阳 · 归老\",\"modern\":\"湖北襄阳\",\"lon\":112.15,\"lat\":32.04,\"period\":\"733—740 · 归隐终老\",\"event\":\"背疽发作，王昌龄游襄阳来会，纵情宴谑以致疾发而逝。李白过襄阳，惟见「孟夫子」风流何处。\",\"poems\":[]}\n ]"}, {"id": 11, "name": "王昌龄", "zi": "少伯", "hao": "", "dynasty": "唐", "years": "698—757", "title": "七绝圣手", "intro": "盛唐边塞诗人，七言绝句与李白并称双璧。《出塞》被誉为唐人七绝压卷之作。仕途坎坷，两度被贬，终罹乱遇难。", "story": "他早年曾赴西北边塞，亲眼看过大漠孤城，所以笔下的关山月总有金石声。后人评他的七绝「深情幽怨，意旨微茫，尤入神品」。\n可诗名太盛，命却太薄：一贬岭南，再贬龙标，李白远在江南还为他写下「我寄愁心与明月」。安史乱起，他返乡途经亳州，竟被嫉妒才名的刺史闾丘晓杀害。后来张镐处决闾丘晓，晓求饶家有老母，张镐只答了一句：「王昌龄之亲，欲与谁养？」", "storyTitle": "一片冰心", "journey": "[\n {\"place\":\"长安\",\"modern\":\"陕西西安\",\"lon\":108.94,\"lat\":34.27,\"period\":\"698—724 · 早年\",\"event\":\"京兆长安人，早年躬耕灞上，曾西北出塞、东南漫游，诗名渐起。\",\"poems\":[]},\n {\"place\":\"凉州\",\"modern\":\"甘肃武威\",\"lon\":102.64,\"lat\":37.93,\"period\":\"约724—727 · 出塞\",\"event\":\"游河西边塞，亲历大漠孤城，秦时明月汉时关、黄沙百战穿金甲，皆此地所见。\",\"poems\":[33,35]},\n {\"place\":\"江宁\",\"modern\":\"江苏南京\",\"lon\":118.80,\"lat\":32.06,\"period\":\"约740—747 · 江宁丞\",\"event\":\"中进士后仕途蹉跌，出任江宁丞，人呼「王江宁」；江南采莲，闻歌始觉有人来。\",\"poems\":[36]},\n {\"place\":\"润州\",\"modern\":\"江苏镇江\",\"lon\":119.45,\"lat\":32.21,\"period\":\"747 · 芙蓉楼送别\",\"event\":\"自江宁赴润州，于芙蓉楼饯别辛渐：洛阳亲友如相问，一片冰心在玉壶。\",\"poems\":[34]},\n {\"place\":\"龙标\",\"modern\":\"湖南洪江\",\"lon\":110.09,\"lat\":27.21,\"period\":\"748—757 · 贬所\",\"event\":\"以「不护细行」再贬龙标尉，李白寄愁心与明月，随风直到夜郎西。安史乱起北还，途经亳州为闾丘晓所杀。\",\"poems\":[]}\n ]"}, {"id": 12, "name": "李商隐", "zi": "义山", "hao": "玉溪生", "dynasty": "唐", "years": "约813—858", "title": "诗坛情圣", "intro": "晚唐最缠绵也最晦涩的诗人，与杜牧并称「小李杜」。一生陷于牛李党争夹缝，沉沦下僚。诗深情绵邈，用典精工，《无题》诸篇写尽爱情的隐微曲折。", "story": "他的一生像他自己的诗：开成二年令狐绹延誉得中进士，次年却娶了「李党」王茂元之女，从此被「牛党」视作背恩之人，一生辗转于各处幕府，漂泊至死。\n妻子王氏早逝后，他在梓州幕府写下「此情可待成追忆」。四十五岁郁郁而终。后人爱他的诗，也叹他的命：把最深的深情，都藏进了无人能解的典故里。", "storyTitle": "锦瑟无端", "journey": "[\n {\"place\":\"怀州 · 河内\",\"modern\":\"河南沁阳\",\"lon\":113.27,\"lat\":35.09,\"period\":\"约813—833 · 幼年\",\"event\":\"生于怀州河内，十岁丧父，家境困厄，佣书贩舂以奉母。\",\"poems\":[]},\n {\"place\":\"长安\",\"modern\":\"陕西西安\",\"lon\":108.94,\"lat\":34.27,\"period\":\"837—846 · 进士与党争\",\"event\":\"令狐绹延誉得中进士，次年入泾原王茂元幕并娶其女，牛党目为背恩；夕阳无限好，只是近黄昏，登乐游原皆在此间。\",\"poems\":[39,40]},\n {\"place\":\"桂林\",\"modern\":\"广西桂林\",\"lon\":110.29,\"lat\":25.27,\"period\":\"847—848 · 桂管幕府\",\"event\":\"随郑亚赴桂管观察使幕，瘴江南去，乡思愈切。\",\"poems\":[]},\n {\"place\":\"梓州\",\"modern\":\"四川三台\",\"lon\":105.09,\"lat\":31.11,\"period\":\"851—855 · 东川幕府\",\"event\":\"妻王氏病逝，应柳仲郢之聘入东川幕府；巴山夜雨、锦瑟无端，晚岁深情皆成于此。\",\"poems\":[37,38]},\n {\"place\":\"荥阳\",\"modern\":\"河南荥阳\",\"lon\":113.44,\"lat\":34.79,\"period\":\"858 · 归葬\",\"event\":\"罢幕北归，郁郁而终，年约四十六，葬于荥阳祖茔。\",\"poems\":[]}\n ]"}, {"id": 13, "name": "杜牧", "zi": "牧之", "hao": "樊川居士", "dynasty": "唐", "years": "803—852", "title": "小杜", "intro": "晚唐诗人，宰相杜佑之孙。注《孙子兵法》而论兵，怀经世之志而不遇。诗俊爽峭健，七绝尤佳，与李商隐并称「小李杜」。", "story": "二十三岁写《阿房宫赋》名动京师，自诩知兵。他一生最大的舞台却是扬州：牛僧孺幕中掌书记，昼理公务、夜游歌楼，留下「十年一觉扬州梦，赢得青楼薄幸名」。\n他自己也知这只是逃避——「平生五色线，愿补舜衣裳」。牛李党争的夹缝里，那个想补天的贵公子，最终只留下一路清风明月的绝句，和《阿房宫赋》里「后人哀之而不鉴之」的千钧警语。", "storyTitle": "扬州一梦", "journey": "[\n {\"place\":\"长安\",\"modern\":\"陕西西安\",\"lon\":108.94,\"lat\":34.27,\"period\":\"803—828 · 京兆贵公子\",\"event\":\"宰相杜佑之孙，二十三岁作《阿房宫赋》名动天下，自注《孙子》而知兵。\",\"poems\":[]},\n {\"place\":\"洪州\",\"modern\":\"江西南昌\",\"lon\":115.89,\"lat\":28.68,\"period\":\"828—833 · 江西幕府\",\"event\":\"入江西观察使沈传师幕，少年幕僚，意气纵横。\",\"poems\":[]},\n {\"place\":\"扬州\",\"modern\":\"江苏扬州\",\"lon\":119.42,\"lat\":32.39,\"period\":\"833—835 · 淮南幕府\",\"event\":\"牛僧孺幕掌书记，昼理公务夜游歌楼；十年一觉扬州梦，赢得青楼薄幸名。夜泊秦淮，犹闻后庭遗曲。\",\"poems\":[43]},\n {\"place\":\"黄州\",\"modern\":\"湖北黄冈\",\"lon\":114.87,\"lat\":30.45,\"period\":\"842—844 · 黄州刺史\",\"event\":\"出为黄州刺史，江边磨洗折戟——东风不与周郎便，铜雀春深锁二乔。\",\"poems\":[44]},\n {\"place\":\"池州\",\"modern\":\"安徽池州\",\"lon\":107.49,\"lat\":30.66,\"period\":\"844—846 · 池州刺史\",\"event\":\"转守池州，秋山石径、清明杏花村，皆此时笔底风物。\",\"poems\":[41,42]},\n {\"place\":\"湖州\",\"modern\":\"浙江湖州\",\"lon\":120.09,\"lat\":30.87,\"period\":\"850 · 湖州刺史\",\"event\":\"求守湖州得偿夙愿；次年内召长安为中书舍人，寻病卒，年五十。\",\"poems\":[]}\n ]"}, {"id": 14, "name": "柳永", "zi": "耆卿", "hao": "白衣卿相", "dynasty": "宋", "years": "约984—约1053", "title": "慢词圣手", "intro": "北宋第一位专力写词的人，大力创作慢词，扩大了词的容量与题材。「凡有井水饮处，即能歌柳词」。仕途潦倒，一生流连坊曲，以毕生心血填词。", "story": "他考了四次进士都落第，一气写下「忍把浮名，换了浅斟低唱」。仁宗放榜时记得这句，朱笔一批：「且去浅斟低唱，何要浮名？」从此他自号「奉旨填词柳三变」，索性把功名换成了人间烟火。\n他给乐工歌妓写词，写市井的离别与相思，写到「凡有井水饮处，即能歌柳词」。晚年改名柳永才中了进士，做过小小屯田员外郎，卒于润州。据说死后家无余财，是歌妓们集资把他葬的——香花纸钱，年年清明，「吊柳七」。", "storyTitle": "奉旨填词", "journey": "[\n {\"place\":\"崇安\",\"modern\":\"福建武夷山\",\"lon\":118.03,\"lat\":27.76,\"period\":\"约984—1004 · 少年\",\"event\":\"生于崇安白袍巷，工词善音律，自号「奉旨填词柳三变」之前，先有白袍少年郎。\",\"poems\":[]},\n {\"place\":\"杭州\",\"modern\":\"浙江杭州\",\"lon\":120.16,\"lat\":30.25,\"period\":\"约1004—1005 · 干谒\",\"event\":\"谒两浙转运使孙何，一阕《望海潮》写尽钱塘繁华——三秋桂子，十里荷花，相传金主亮闻歌遂起投鞭渡江之志。\",\"poems\":[46]},\n {\"place\":\"汴京\",\"modern\":\"河南开封\",\"lon\":114.31,\"lat\":34.80,\"period\":\"1009—1034 · 屡试不第\",\"event\":\"四应进士皆黜落，仁宗批「且去浅斟低唱」；遂浪迹坊曲，为歌妓作词，执手相看泪眼，晓风残月柳七词。\",\"poems\":[45,47]},\n {\"place\":\"润州\",\"modern\":\"江苏镇江\",\"lon\":119.45,\"lat\":32.21,\"period\":\"1046—约1053 · 晚岁\",\"event\":\"晚年方进士及第，官至屯田员外郎，世称柳屯田；暮雨洒江天时倚阑凝愁，卒于润州，相传歌妓集资而葬。\",\"poems\":[48]}\n]"}, {"id": 15, "name": "欧阳修", "zi": "永叔", "hao": "醉翁、六一居士", "dynasty": "宋", "years": "1007—1072", "title": "一代文宗", "intro": "北宋诗文革新运动领袖，唐宋八大家之一。奖掖后进不遗余力，三苏、曾巩、王安石皆出其门。亦工词，深婉清丽。", "story": "四岁丧父，家贫，母亲郑氏以芦荻画地教字。他考进士时连中三元，却被评为「风采太过」抑为第二，从此一生锋芒不掩：庆历新政他仗义执言，被贬滁州，写下《醉翁亭记》——「醉翁之意不在酒」。\n他最大的功业却是识人：嘉祐二年他主持贡举，一榜取中苏轼、苏辙、曾巩、程颢、张载——千年科举最耀眼的一榜。他说「老夫当避路，放他出一头地」，说完，真的避路了。", "storyTitle": "醉翁之意", "journey": "[\n {\"place\":\"绵州\",\"modern\":\"四川绵阳\",\"lon\":104.75,\"lat\":31.47,\"period\":\"1007 · 生于任所\",\"event\":\"父任绵州推官，生于此；四岁丧父，随母归吉州，画荻教子。\",\"poems\":[]},\n {\"place\":\"洛阳\",\"modern\":\"河南洛阳\",\"lon\":112.45,\"lat\":34.62,\"period\":\"1031—1034 · 西京幕府\",\"event\":\"为西京留守推官，与梅尧臣、尹洙游，倡为古文，钱惟演幕中风流最盛。\",\"poems\":[]},\n {\"place\":\"汴京\",\"modern\":\"河南开封\",\"lon\":114.31,\"lat\":34.80,\"period\":\"1034—1036 · 馆阁谏垣\",\"event\":\"入馆阁、知谏院，直言极谏；元夕灯市，月上柳梢头。\",\"poems\":[49,51]},\n {\"place\":\"夷陵\",\"modern\":\"湖北宜昌\",\"lon\":111.29,\"lat\":30.69,\"period\":\"1036—1038 · 贬峡州\",\"event\":\"为范仲淹鸣不平，贬峡州夷陵县令；二月山城未见花，残雪压枝犹有橘。\",\"poems\":[52]},\n {\"place\":\"滁州\",\"modern\":\"安徽滁州\",\"lon\":118.32,\"lat\":32.30,\"period\":\"1045—1048 · 醉翁\",\"event\":\"庆历新政败，坐朋党贬滁州；醉翁之意不在酒，在乎山水之间也。\",\"poems\":[]},\n {\"place\":\"颍州\",\"modern\":\"安徽阜阳\",\"lon\":115.81,\"lat\":32.90,\"period\":\"1071—1072 · 归老\",\"event\":\"致仕居颍州西湖，轻舟短棹，绿水逶迤，惊起沙禽掠岸飞；同年卒，谥文忠。\",\"poems\":[50]}\n]"}, {"id": 16, "name": "王安石", "zi": "介甫", "hao": "半山", "dynasty": "宋", "years": "1021—1086", "title": "王荆公", "intro": "北宋政治家、文学家，「唐宋八大家」之一。主持熙宁变法，以「天变不足畏，祖宗不足法，人言不足恤」之勇气行新法。诗峭拔简劲，晚年起于炉火纯青。", "story": "他是那个时代最固执也最干净的人。做了两任宰相，罢相后退居江宁半山园，骑一头驴。政敌司马光评价：「人言安石奸邪，则毁之太过；但不晓事，又执拗耳。」\n变法失败千年，功罪聚讼不休，但他的私德连对手也无话可说：不好声色，不爱官职，不殖货利。失败了的是新法，不曾失败的是那句「天变不足畏，祖宗不足法，人言不足恤」——九百年后，仍掷地有声。", "storyTitle": "拗相公", "journey": "[\n {\"place\":\"临川\",\"modern\":\"江西抚州\",\"lon\":116.36,\"lat\":27.98,\"period\":\"1021—1039 · 少年\",\"event\":\"生于临川，随父宦游各地，过目不忘；曾巩称其文「善诵读，不为愚」。\",\"poems\":[]},\n {\"place\":\"鄞县\",\"modern\":\"浙江宁波\",\"lon\":121.56,\"lat\":29.87,\"period\":\"1047—1049 · 鄞县令\",\"event\":\"知鄞县，起堤堰、决陂塘、贷谷于民——青苗法之雏形已在小县试验。\",\"poems\":[]},\n {\"place\":\"杭州\",\"modern\":\"浙江杭州\",\"lon\":120.16,\"lat\":30.25,\"period\":\"1050 · 途经\",\"event\":\"自鄞返临川，道经越州登飞来峰：不畏浮云遮望眼，自缘身在最高层。\",\"poems\":[55]},\n {\"place\":\"汴京\",\"modern\":\"河南开封\",\"lon\":114.31,\"lat\":34.80,\"period\":\"1058—1076 · 变法\",\"event\":\"上仁宗万言书不报；神宗立，拜参知政事，行新法八年，两度拜相两度罢——爆竹声中一岁除，总把新桃换旧符。\",\"poems\":[56]},\n {\"place\":\"瓜洲\",\"modern\":\"江苏扬州邗江\",\"lon\":119.42,\"lat\":32.34,\"period\":\"1075 · 复相途中\",\"event\":\"再拜相自江宁赴汴，夜泊瓜洲：春风又绿江南岸，明月何时照我还。\",\"poems\":[53]},\n {\"place\":\"江宁\",\"modern\":\"江苏南京\",\"lon\":118.80,\"lat\":32.06,\"period\":\"1076—1086 · 半山园\",\"event\":\"罢相退居江宁，营半山园，骑驴游山，写「墙角数枝梅」；元祐元年卒，谥文，后追贬又追复舒王。\",\"poems\":[54]}\n ]"}, {"id": 17, "name": "陆游", "zi": "务观", "hao": "放翁", "dynasty": "宋", "years": "1125—1210", "title": "亘古男儿", "intro": "南宋爱国诗人，存诗九千三百余首，为存诗最多的诗人。一生志在恢复中原，临终犹作《示儿》。诗雄浑豪放与清新圆润兼擅。", "story": "他与唐琬的沈园之遇是南宋最痛的爱情：一阕《钗头凤》题壁，「错、错、错」，从此「伤心桥下春波绿，曾是惊鸿照影来」。\n他的主线却是北伐：四十八岁从军南郑，铁衣上渡渭水，「铁马秋风大散关」是他一生最亮的八个月。此后六十年，从「胡未灭，鬓先秋」写到临终的《示儿》——死去之前，他还惦记着让儿子家祭时别忘了告诉他王师收复中原的消息。梁启超叹：「亘古男儿一放翁。」", "storyTitle": "铁马冰河", "journey": "[\n {\"place\":\"山阴\",\"modern\":\"浙江绍兴\",\"lon\":120.58,\"lat\":30.01,\"period\":\"1125—1163 · 家乡与沈园\",\"event\":\"生于淮上舟中，靖康之乱随家南归山阴；二十岁与唐琬结褵，被迫离异，沈园重逢题《钗头凤》于壁。\",\"poems\":[60]},\n {\"place\":\"临安\",\"modern\":\"浙江杭州\",\"lon\":120.16,\"lat\":30.25,\"period\":\"1153—1154 · 锁厅试\",\"event\":\"赴临安应锁厅试，取为第一，因名列秦桧孙前而遭黜落，遂归里力学。\",\"poems\":[]},\n {\"place\":\"镇江\",\"modern\":\"江苏镇江\",\"lon\":119.42,\"lat\":32.20,\"period\":\"1163—1164 · 通判\",\"event\":\"任镇江通判，力赞张浚北伐，亲至前线观兵；隆兴和议成，壮志暂挫。\",\"poems\":[]},\n {\"place\":\"南郑\",\"modern\":\"陕西汉中\",\"lon\":107.03,\"lat\":33.07,\"period\":\"1172 · 从军南郑\",\"event\":\"入王炎幕府赞理军务，铁衣白马戍大散关，射虎、雪夜欢宴——一生最亮的八个月；幕府撤，泪洒南郑。\",\"poems\":[]},\n {\"place\":\"成都\",\"modern\":\"四川成都\",\"lon\":104.07,\"lat\":30.67,\"period\":\"1173—1178 · 蜀中八年\",\"event\":\"历蜀州、嘉州、成都诸职，参范成大幕，以「放翁」自号，花时遍游锦城。\",\"poems\":[]},\n {\"place\":\"山阴 · 三山\",\"modern\":\"浙江绍兴\",\"lon\":120.62,\"lat\":30.05,\"period\":\"1179—1210 · 老家\",\"event\":\"归隐三山，游山西村、卧听风雨，梦回铁马冰河；八十五岁临终作《示儿》，不忘告乃翁。\",\"poems\":[57,58,59]}\n]"}];
export const POEMS = [{"id": 1, "title": "饮酒", "subtitle": "其五", "poetId": 1, "dynasty": "魏晋", "genre": "五言古诗", "paragraphs": "结庐在人境，而无车马喧。\n问君何能尔？心远地自偏。\n采菊东篱下，悠然见南山。\n山气日夕佳，飞鸟相与还。\n此中有真意，欲辨已忘言。", "annotation": "结庐：建造屋舍。尔：如此、这样。日夕：傍晚。相与还：结伴归巢。", "translation": "把屋舍建在人来人往之地，却听不见车马的喧闹。问我为什么能这样？心离尘世远了，住处自然就偏静了。东篱下采菊，不经意间抬头，南山恰好映入眼帘。暮色中山气缭绕，飞鸟结伴归巢。这里头有生活的真意，想分辨清楚，却已忘了怎么说。", "appreciation": "全诗没有一个\"隐\"字，却句句是隐居的况味。\"心远地自偏\"是全篇诗眼——避世不在身，而在心。\"采菊东篱下，悠然见南山\"中一个\"见\"字（非\"望\"字），写尽物我两忘的偶然与天成，被王国维推为\"无我之境\"的典范。", "mood": "田园", "famousLine": "采菊东篱下，悠然见南山", "poetName": "陶渊明"}, {"id": 2, "title": "归园田居", "subtitle": "其三", "poetId": 1, "dynasty": "魏晋", "genre": "五言古诗", "paragraphs": "种豆南山下，草盛豆苗稀。\n晨兴理荒秽，带月荷锄归。\n道狭草木长，夕露沾我衣。\n衣沾不足惜，但使愿无违。", "annotation": "晨兴：早起。荒秽：杂草。荷：扛着。愿无违：不违背归隐的心愿。", "translation": "在南山下种豆，草长得比豆苗还茂盛。清早起来清除杂草，傍晚顶着月光扛锄头回家。狭窄的小路上草木丛生，晚露打湿了我的衣裳。衣裳湿了不值得可惜，只要不违背我的心愿就好。", "appreciation": "种豆偏偏\"豆苗稀\"，可见诗人实在不擅农事——但他毫不在意。全诗最动人的是\"带月荷锄归\"：一天的劳作在月光里收束成一幅剪影，辛苦被诗意轻轻托住。结句\"但使愿无违\"交代了一切代价的取舍：身体之苦，换精神自由，值。", "mood": "田园", "famousLine": "带月荷锄归", "poetName": "陶渊明"}, {"id": 3, "title": "静夜思", "subtitle": "", "poetId": 2, "dynasty": "唐", "genre": "五言绝句", "paragraphs": "床前明月光，疑是地上霜。\n举头望明月，低头思故乡。", "annotation": "疑：好像。霜：月光清冷洁白，故以霜为喻。", "translation": "床前洒满明亮的月光，好像地上铺了一层秋霜。抬头望着天上的明月，低下头来，思念起远方的故乡。", "appreciation": "二十个字，无一奇字险句，却成了中国人会说的第一首诗。妙处在两个动作：举头，是望月；低头，是望心。月光是媒介，把天涯游子和千里故乡照在同一个圆里。不写愁而愁自现，不写乡而乡自远。", "mood": "思乡", "famousLine": "低头思故乡", "poetName": "李白"}, {"id": 4, "title": "望庐山瀑布", "subtitle": "", "poetId": 2, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "日照香炉生紫烟，遥看瀑布挂前川。\n飞流直下三千尺，疑是银河落九天。", "annotation": "香炉：庐山香炉峰。川：此指瀑布如白练挂于山前。九天：天之极高处。", "translation": "阳光照在香炉峰上，升起紫色的云烟。远远望去，瀑布像一条白练悬挂在山前。水流飞泻而下三千尺，让人疑心是银河从九重天倾落人间。", "appreciation": "一个\"生\"字写出烟云的流动，一个\"挂\"字写出瀑布的静止之姿，而\"疑是银河落九天\"则是只有李白才敢想的比喻——把人间的山川直接接到天上。夸饰到极处反而逼真，这就是\"诗仙\"的想象特权。", "mood": "山水", "famousLine": "飞流直下三千尺，疑是银河落九天", "poetName": "李白"}, {"id": 5, "title": "月下独酌", "subtitle": "其一", "poetId": 2, "dynasty": "唐", "genre": "五言古诗", "paragraphs": "花间一壶酒，独酌无相亲。\n举杯邀明月，对影成三人。\n月既不解饮，影徒随我身。\n暂伴月将影，行乐须及春。\n我歌月徘徊，我舞影零乱。\n醒时同交欢，醉后各分散。\n永结无情游，相期邈云汉。", "annotation": "无相亲：没有亲近之人。不解饮：不懂得饮酒之趣。无情游：与无情之物（月与影）的交游。邈云汉：远在天河。", "translation": "花丛间摆一壶酒，自斟自饮没有亲友。举起酒杯邀请明月，加上自己的影子，恰好凑成三个人。月亮不懂得饮酒，影子也只徒然跟随我身。姑且伴着月与影，趁这春光及时行乐。我歌唱时月亮徘徊不去，我起舞时影子摇曳零乱。清醒时一同欢聚，醉后便各自飘散。愿与它们结下忘却世情的交游，相约在遥远的天河再会。", "appreciation": "孤独被李白写成了排场：明明独酌，偏要\"邀月对影成三人\"，把冷清闹成热闹。可\"月不解饮，影徒随身\"，热闹到极处恰恰是孤独到极处。结尾却陡然升华——与无情之物结永恒之游，孤独至此，已是境界。", "mood": "月夜", "famousLine": "举杯邀明月，对影成三人", "poetName": "李白"}, {"id": 6, "title": "早发白帝城", "subtitle": "", "poetId": 2, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "朝辞白帝彩云间，千里江陵一日还。\n两岸猿声啼不住，轻舟已过万重山。", "annotation": "白帝：白帝城，地势极高，晨霞映照故云\"彩云间\"。江陵：今湖北荆州。住：停歇。", "translation": "清晨告别高入彩云的白帝城，千里之遥的江陵，一天就到了。两岸猿声还在耳边不停地啼叫，轻快的小船已驶过万重山峦。", "appreciation": "这首诗写于流放夜郎途中遇赦返回之时。五十九岁的李白突然重获自由，喜从天降，于是千里水路成了\"一日还\"，万重山成了身后轻烟。猿声未停而轻舟已过——速度感里全是心跳。没有一字言喜，而狂喜扑面而来。", "mood": "豪放", "famousLine": "轻舟已过万重山", "poetName": "李白"}, {"id": 7, "title": "山居秋暝", "subtitle": "", "poetId": 3, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "空山新雨后，天气晚来秋。\n明月松间照，清泉石上流。\n竹喧归浣女，莲动下渔舟。\n随意春芳歇，王孙自可留。", "annotation": "暝：日暮。浣女：洗衣的女子。春芳歇：春天的芳华凋谢。王孙：贵族子弟，此为诗人自指，反用《楚辞》\"王孙兮归来\"之意。", "translation": "空旷的山中刚下过一场新雨，傍晚的天气带来初秋的凉意。明月透过松林洒下清辉，清泉在山石上淙淙流淌。竹林里传来喧笑，是浣衣女子归来；莲叶摇动，是渔舟顺流而下。任凭春天的芳菲消歇吧，这秋色里，王孙自可长留。", "appreciation": "颔联\"明月松间照，清泉石上流\"，一静一动，光影与声响俱在，是不着一色的水墨。颈联先闻竹喧、后见人归，先觉莲动、方知舟来——倒装的写法让画面有了听觉的先导。山居如此，人间朝廷的纷扰，自然是\"随意春芳歇\"了。", "mood": "山水", "famousLine": "明月松间照，清泉石上流", "poetName": "王维"}, {"id": 8, "title": "鹿柴", "subtitle": "", "poetId": 3, "dynasty": "唐", "genre": "五言绝句", "paragraphs": "空山不见人，但闻人语响。\n返景入深林，复照青苔上。", "annotation": "鹿柴：辋川别业中的一处地名。但：只。返景：夕阳返照的光。", "translation": "空旷的山中看不见人影，只偶尔听得有人说话的声音。夕阳的余晖穿过深林，又照在那片青苔上。", "appreciation": "二十个字全是\"空\"的辩证法：看不见人，却有人语；人语愈清晰，山愈空寂。光影入林照苔——光愈亮，林愈深。王维以声写寂、以光写暗，四句诗是一堂禅意的\"以有衬无\"，也是他晚年心境的写照。", "mood": "山水", "famousLine": "空山不见人，但闻人语响", "poetName": "王维"}, {"id": 9, "title": "送元二使安西", "subtitle": "", "poetId": 3, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "渭城朝雨浥轻尘，客舍青青柳色新。\n劝君更尽一杯酒，西出阳关无故人。", "annotation": "渭城：秦时咸阳城，在长安西北。浥：湿润。更尽：再喝完。阳关：在今甘肃敦煌西南，出关即离中原。", "translation": "渭城清晨的细雨打湿了路上轻尘，客舍旁的柳枝被洗得青翠一新。劝你再干了这杯酒吧，向西出了阳关，就再没有我这样的老朋友了。", "appreciation": "送别诗写到极致，往往只是一个小动作。\"更尽一杯酒\"——不是不忍别，是想再拖延一刻。前两句的朝雨、青柳，把离别的空气洗得清清爽爽；后两句一出，千年来所有送行的酒桌上，都有了这同一句话。", "mood": "送别", "famousLine": "劝君更尽一杯酒，西出阳关无故人", "poetName": "王维"}, {"id": 10, "title": "九月九日忆山东兄弟", "subtitle": "", "poetId": 3, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "独在异乡为异客，每逢佳节倍思亲。\n遥知兄弟登高处，遍插茱萸少一人。", "annotation": "山东：指华山以东的家乡蒲州。茱萸：香气浓烈的植物，重阳节佩之以辟邪。", "translation": "独自客居异乡，每到佳节就加倍思念亲人。遥想兄弟们今日登高远望，身上都插着茱萸，唯独少了我一人。", "appreciation": "写此诗时王维年仅十七。\"每逢佳节倍思亲\"之所以千古不移，在于它道破了思亲的\"倍数效应\"：平日尚可压抑，节日的热闹一来，孤独立刻翻倍。更妙的是后两句不说自己如何想兄弟，反写兄弟登高时发现\"少一人\"——把思念写成了一场双向的缺位。", "mood": "思乡", "famousLine": "每逢佳节倍思亲", "poetName": "王维"}, {"id": 11, "title": "春望", "subtitle": "", "poetId": 4, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "国破山河在，城春草木深。\n感时花溅泪，恨别鸟惊心。\n烽火连三月，家书抵万金。\n白头搔更短，浑欲不胜簪。", "annotation": "国：国都长安。浑：简直。不胜簪：插不住簪子。", "translation": "国都沦陷，山河依旧，长安城春天来了，到处草木深深。感伤时局，见花开反而落泪；怅恨离别，闻鸟鸣反而惊心。战火连绵已过了三个月，家书难得，一封抵得上万金。愁白的头发越搔越短，简直要插不住簪子了。", "appreciation": "\"国破山河在\"五字抵得上千言：物是人非，山河无言。花本是乐景，鸟本是常声，此刻却\"溅泪\"\"惊心\"——不是景变了，是心碎了。\"家书抵万金\"从此成为中国人写\"音讯\"的最高价码。全诗沉郁顿挫，字字都是时代的裂痕。", "mood": "家国", "famousLine": "国破山河在，城春草木深", "poetName": "杜甫"}, {"id": 12, "title": "春夜喜雨", "subtitle": "", "poetId": 4, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "好雨知时节，当春乃发生。\n随风潜入夜，润物细无声。\n野径云俱黑，江船火独明。\n晓看红湿处，花重锦官城。", "annotation": "乃：就、便。潜：悄悄地。红湿处：被雨打湿的红花。花重：花因带雨而沉重。锦官城：成都。", "translation": "好雨懂得时令，正值春天便降落。随着春风在夜里悄悄落下，无声地滋润着万物。田野小径上乌云漆黑，只有江船上的灯火独自明亮。等天亮去看那红花带雨之处，成都城里的花，开得沉甸甸一片。", "appreciation": "题目一个\"喜\"字统摄全篇，但通篇没有一个\"喜\"字。\"潜入夜\"\"细无声\"——把雨写成了谦谦君子，做好事而不惊动人。这既是春雨，也是杜甫心中理想政治的样子。末句悬想明日繁花，喜意这才破纸而出。", "mood": "田园", "famousLine": "随风潜入夜，润物细无声", "poetName": "杜甫"}, {"id": 13, "title": "月夜忆舍弟", "subtitle": "", "poetId": 4, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "戍鼓断人行，边秋一雁声。\n露从今夜白，月是故乡明。\n有弟皆分散，无家问死生。\n寄书长不达，况乃未休兵。", "annotation": "戍鼓：戍楼上的更鼓。断人行：宵禁，路上断绝行人。舍弟：对人称自己的弟弟。况乃：何况是。", "translation": "戍楼更鼓响过，路上不见行人，边地的秋空中，传来孤雁的哀鸣。从今夜就进了白露节气，月亮还是故乡的最明。兄弟们各自离散，家已不存，生死无处打听。寄出去的书信总是送不到，何况战乱还没有平息。", "appreciation": "\"月是故乡明\"是典型的\"无理而妙\"：天下的月本无二致，偏心的人才有故乡的月。这句诗的高明在于坦白——思念本来就不讲道理。后半首转入生死茫茫的追问，个人的怀人背后，是整个战乱时代的骨肉离散。", "mood": "月夜", "famousLine": "露从今夜白，月是故乡明", "poetName": "杜甫"}, {"id": 14, "title": "登高", "subtitle": "", "poetId": 4, "dynasty": "唐", "genre": "七言律诗", "paragraphs": "风急天高猿啸哀，渚清沙白鸟飞回。\n无边落木萧萧下，不尽长江滚滚来。\n万里悲秋常作客，百年多病独登台。\n艰难苦恨繁霜鬓，潦倒新停浊酒杯。", "annotation": "渚：水中小洲。落木：落叶。百年：一生，此指晚年。新停：最近戒酒。", "translation": "风急天高，猿声悲哀；小洲清冷，白沙之上鸟儿盘旋。无边的落叶萧萧而下，望不尽的长江滚滚奔来。悲对秋色，感慨万里漂泊常年为客；一生多病，今日独自登上高台。时世艰难，愁白了双鬓；穷困潦倒，偏偏又戒了消愁的酒。", "appreciation": "被历代评家推为\"古今七律第一\"。前四句写景，\"无边\"\"不尽\"把秋意与江水都推向时间的无穷；后四句写身世，万里、悲秋、作客、多病、独登——数层愁绪叠在一处，读来一气贯注。末句连借酒浇愁都不可得，悲至此，已无处可排遣。", "mood": "悲秋", "famousLine": "无边落木萧萧下，不尽长江滚滚来", "poetName": "杜甫"}, {"id": 15, "title": "赋得古原草送别", "subtitle": "", "poetId": 5, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "离离原上草，一岁一枯荣。\n野火烧不尽，春风吹又生。\n远芳侵古道，晴翠接荒城。\n又送王孙去，萋萋满别情。", "annotation": "离离：茂盛的样子。远芳：蔓延到远方的芳草。王孙：此指远行的友人。萋萋：草茂盛的样子。", "translation": "原野上长满茂盛的青草，年年岁岁枯了又荣。野火烧不尽它，春风一吹又重新生长。芳草远伸，渐渐侵占了古道；阳光下的翠绿，连接着荒城。又要送友人远行了，这茂密的萋萋芳草，满满都是离别之情。", "appreciation": "据说此诗是白居易十六岁的应考习作，顾况先以其名打趣\"长安米贵，居大不易\"，读到\"野火烧不尽\"二句，当即改口：\"有句如此，居天下有甚难！\"\n\"野火—春风\"两句写尽生命的韧性，也是全诗从送别之愁里挣出来的一股劲：草会枯，但烧不尽；人会别，但情如春草，更行更远还生。", "mood": "送别", "famousLine": "野火烧不尽，春风吹又生", "poetName": "白居易"}, {"id": 16, "title": "钱塘湖春行", "subtitle": "", "poetId": 5, "dynasty": "唐", "genre": "七言律诗", "paragraphs": "孤山寺北贾亭西，水面初平云脚低。\n几处早莺争暖树，谁家新燕啄春泥。\n乱花渐欲迷人眼，浅草才能没马蹄。\n最爱湖东行不足，绿杨阴里白沙堤。", "annotation": "水面初平：湖水与堤岸齐平，指春水初涨。云脚低：云气低垂，与水面相连。暖树：向阳的树。行不足：游不够。", "translation": "从孤山寺北到贾亭西面，春水初涨与岸齐平，云气低垂与湖水相连。几只早出的黄莺争着飞向向阳的树枝，不知是谁家的新燕正衔泥筑巢。纷繁的春花渐渐要迷住人的眼睛，浅浅的春草刚刚能够没过马蹄。最爱湖东的景致，总也游不够，那绿杨荫里的白沙堤。", "appreciation": "一首\"早春\"的工笔画：莺是\"早莺\"、燕是\"新燕\"、花\"渐欲\"、草\"才能\"——处处扣住一个\"初\"字，万物都处于将盛未盛的节点，满纸是生的躁动。尾句\"行不足\"三字收束，游人不肯走，春色也就永远走不完。", "mood": "山水", "famousLine": "乱花渐欲迷人眼，浅草才能没马蹄", "poetName": "白居易"}, {"id": 17, "title": "暮江吟", "subtitle": "", "poetId": 5, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "一道残阳铺水中，半江瑟瑟半江红。\n可怜九月初三夜，露似真珠月似弓。", "annotation": "瑟瑟：碧绿色，指未被残阳照到的江面。可怜：可爱。", "translation": "一道残阳的余晖平铺在江面上，半江是碧绿，半江是艳红。最可爱的是这九月初三的夜晚，露珠圆润如珍珠，新月弯弯如弯弓。", "appreciation": "两句写尽夕照的物理：残阳贴着水面\"铺\"来，受光半江红、背光半江碧，颜色学般精准，又是何等天真的欢喜。后两句把九月初三这个平常日子过成了节日——露与月，一珠一弓，皆是小小圆满。白居易的可爱，在于他永远肯为寻常黄昏驻足。", "mood": "月夜", "famousLine": "露似真珠月似弓", "poetName": "白居易"}, {"id": 18, "title": "水调歌头", "subtitle": "明月几时有", "poetId": 6, "dynasty": "宋", "genre": "词", "paragraphs": "明月几时有？把酒问青天。不知天上宫阙，今夕是何年。\n我欲乘风归去，又恐琼楼玉宇，高处不胜寒。起舞弄清影，何似在人间。\n\n转朱阁，低绮户，照无眠。不应有恨，何事长向别时圆？\n人有悲欢离合，月有阴晴圆缺，此事古难全。但愿人长久，千里共婵娟。", "annotation": "宫阙：月中宫殿。琼楼玉宇：月中仙宫。婵娟：指明月。绮户：雕花的门窗。", "translation": "明月从什么时候开始有的？我端着酒杯询问青天。不知天上的宫殿，今晚是哪一年。想乘着清风回到天上去，又怕月宫里玉砌的高楼，受不了那份高寒。起身舞弄月下的清影，哪里比得上留在人间。\n月光转过朱红的楼阁，低低地照进雕花的窗户，照着无眠的人。月亮不该有什么怨恨吧，为何总在人们离别时才圆？人有悲欢离合，月有阴晴圆缺，这种事自古难以两全。只希望彼此都能平安长久，隔着千里，共赏这一轮明月。", "appreciation": "丙辰中秋，苏轼在密州想念七年未见的弟弟苏辙，写下此词。上半阕问天：去还是不去？——\"高处不胜寒\"，最终选择留在人间，这是他对仕途的全部态度。下半阕问月：为何偏在离别时圆？——随即自己答了：此事古难全。\n词从豪问到哲思再到祝愿，完成了一次自我安慰，也安慰了此后千年所有中秋不能团圆的人。", "mood": "月夜", "famousLine": "但愿人长久，千里共婵娟", "poetName": "苏轼"}, {"id": 19, "title": "饮湖上初晴后雨", "subtitle": "其二", "poetId": 6, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "水光潋滟晴方好，山色空蒙雨亦奇。\n若把西湖比西子，淡妆浓抹总相宜。", "annotation": "潋滟：水波荡漾闪光的样子。空蒙：迷茫缥缈。西子：即西施。", "translation": "晴天，西湖水光潋滟，正是明媚动人；雨天，山色空蒙缥缈，也别有一番奇妙。如果把西湖比作美女西施，无论淡妆还是浓抹，都同样恰到好处。", "appreciation": "写西湖的诗千千万，从此全被这两句封顶。妙在\"亦奇\"的平等观：晴有晴的好，雨有雨的奇，不偏爱、不避雨——这本就是苏轼的人生态度。以西子喻湖，\"淡妆浓抹总相宜\"，从此西湖又多了一个名字：西子湖。", "mood": "山水", "famousLine": "欲把西湖比西子，淡妆浓抹总相宜", "poetName": "苏轼"}, {"id": 20, "title": "题西林壁", "subtitle": "", "poetId": 6, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "横看成岭侧成峰，远近高低各不同。\n不识庐山真面目，只缘身在此山中。", "annotation": "横看：从正面看。缘：因为。", "translation": "横着看是连绵山岭，侧着看是高耸山峰，远近高低，姿态各不相同。认不清庐山真正的面目，只因为我自己就置身在这座山中。", "appreciation": "元丰七年，苏轼由黄州改迁汝州，特地上庐山。这是首题壁诗，也是首哲理诗：全诗无一句写景的雕琢，却道破了一个认知困境——身在局中，难识全局。\"不识庐山真面目\"从此成为汉语里对\"当局者迷\"最好的表达。", "mood": "哲理", "famousLine": "不识庐山真面目，只缘身在此山中", "poetName": "苏轼"}, {"id": 21, "title": "如梦令", "subtitle": "常记溪亭日暮", "poetId": 7, "dynasty": "宋", "genre": "词", "paragraphs": "常记溪亭日暮，沉醉不知归路。\n兴尽晚回舟，误入藕花深处。\n争渡，争渡，惊起一滩鸥鹭。", "annotation": "常记：曾记得。藕花：荷花。争渡：奋力划船。鸥鹭：鸥鸟与白鹭。", "translation": "常记得那次溪亭日暮，喝得沉醉，找不到回家的路。游兴满足了，天黑才划船回返，却误入荷花深处。划呀，划呀，惊起了满滩栖息的鸥鹭。", "appreciation": "这是李清照少女时代的作品，是她的\"青春纪念册\"。三十三个字，有酒意、有迷路、有慌乱、有水鸟扑棱棱飞起——全是动态的。少女的天真烂漫与自然的花香鸟趣浑然一体，谁能想到，这双摇桨的手，晚年会写出\"寻寻觅觅\"。", "mood": "闲适", "famousLine": "兴尽晚回舟，误入藕花深处", "poetName": "李清照"}, {"id": 22, "title": "声声慢", "subtitle": "寻寻觅觅", "poetId": 7, "dynasty": "宋", "genre": "词", "paragraphs": "寻寻觅觅，冷冷清清，凄凄惨惨戚戚。\n乍暖还寒时候，最难将息。\n三杯两盏淡酒，怎敌他、晚来风急！\n雁过也，正伤心，却是旧时相识。\n\n满地黄花堆积，憔悴损，如今有谁堪摘？\n守着窗儿，独自怎生得黑！\n梧桐更兼细雨，到黄昏、点点滴滴。\n这次第，怎一个愁字了得！", "annotation": "乍暖还寒：天气忽暖忽冷。将息：调养休息。黄花：菊花。怎生：怎么。次第：光景、情形。", "translation": "整日寻觅，却只寻得一片冷清，徒留凄惨忧戚。忽暖忽寒的时节，最难保养安息。喝下三杯两盏淡酒，怎么抵挡傍晚的急风！大雁飞过，正教人伤心，它们却是当年与我有旧的大雁。满地菊花堆积，已然憔悴枯损，如今还有谁堪与我同摘？守着窗子，独自怎挨到天黑！梧桐上又落细雨，到黄昏，点点滴滴。这般光景，一个\"愁\"字，怎么概括得了！", "appreciation": "开篇十四个叠字，由外到内、由浅入深，把无所依傍的心境一寸寸写尽，千古无人敢再试。雁\"旧时相识\"——旧时雁是传信的，如今信寄给谁？酒是\"淡\"的，天是挨不到黑的，最后收束在一个\"愁\"字又立刻宣布这个字不够用。\n国破、家亡、夫死、物散，一个\"愁\"字确实太轻了。", "mood": "怀人", "famousLine": "寻寻觅觅，冷冷清清，凄凄惨惨戚戚", "poetName": "李清照"}, {"id": 23, "title": "西江月", "subtitle": "夜行黄沙道中", "poetId": 8, "dynasty": "宋", "genre": "词", "paragraphs": "明月别枝惊鹊，清风半夜鸣蝉。\n稻花香里说丰年，听取蛙声一片。\n\n七八个星天外，两三点雨山前。\n旧时茅店社林边，路转溪桥忽见。", "annotation": "别枝：斜枝。社林：土地庙旁的树林。见：同\"现\"。", "translation": "明亮的月光惊起了枝头的乌鹊，半夜清风里传来阵阵蝉鸣。稻花香里，一片蛙声，像在诉说丰年。七八颗星挂在天边，两三点雨落在山前。旧时的茅店还在土地庙树林旁，转过溪桥，它忽然出现在眼前。", "appreciation": "闲居带湖的辛弃疾，难得有这样松弛的夜晚。最妙的是结尾的\"忽见\"：前一刻还念着\"旧时茅店\"在何处，转过溪桥它就出现了——夜行的心跳，被一句平淡的\"忽见\"轻轻接住。武将的词，也有这样温柔的路感。", "mood": "田园", "famousLine": "稻花香里说丰年，听取蛙声一片", "poetName": "辛弃疾"}, {"id": 24, "title": "破阵子", "subtitle": "为陈同甫赋壮词以寄之", "poetId": 8, "dynasty": "宋", "genre": "词", "paragraphs": "醉里挑灯看剑，梦回吹角连营。\n八百里分麾下炙，五十弦翻塞外声，沙场秋点兵。\n\n马作的卢飞快，弓如霹雳弦惊。\n了却君王天下事，赢得生前身后名。可怜白发生！", "annotation": "陈同甫：陈亮，辛弃疾的挚友，同主北伐。八百里：指牛。麾下：部下。五十弦：泛指军乐器。作的卢：战马像的卢马那样。", "translation": "醉里挑亮灯火端详宝剑，梦中回到号角连天的军营。把烤牛肉分给部下，琴瑟奏起悲壮的塞外军歌，秋天的沙场上正在检阅军队。战马奔驰如的卢马般飞快，弓弦响处如惊雷霹雳。本想替君王完成收复天下的大业，赢得生前死后的美名。可惜——满头白发已经丛生！", "appreciation": "从醉里、梦里到沙场点兵，一路疾风骤雨，全是二十三岁夜袭金营的那个辛弃疾。到\"了却君王天下事\"，气壮山河——然后\"可怜白发生\"五个字，一盆冷水兜头浇下。前面九句是梦，最后一句才是现实。这五个字的落差，就是他的一生。", "mood": "壮志", "famousLine": "醉里挑灯看剑，梦回吹角连营", "poetName": "辛弃疾"}, {"id": 25, "title": "观沧海", "subtitle": "", "poetId": 9, "dynasty": "魏晋", "genre": "四言乐府", "paragraphs": "东临碣石，以观沧海。\n水何澹澹，山岛竦峙。\n树木丛生，百草丰茂。\n秋风萧瑟，洪波涌起。\n日月之行，若出其中；\n星汉灿烂，若出其里。\n幸甚至哉，歌以咏志。", "annotation": "碣石：山名，在今河北昌黎。澹澹：水波荡漾的样子。竦峙：高高耸立。星汉：银河。", "translation": "东行登上碣石山，来观赏那苍茫的大海。海水多么宽阔浩荡，山岛高高挺立。岛上树木丛生，百草繁茂。秋风吹过，树木飒飒作响，海中翻涌起巨大的波涛。日月的运行，好像从这浩瀚的海洋中出发；银河星光灿烂，也好像出自这浩瀚的海洋。真是幸运极了，用这首诗歌来抒发心志。", "appreciation": "写沧海，也是在写自己。北征乌桓凯旋，五十三岁的曹操站在碣石山上，把吞吐日月星汉的气象装进了大海——这不是写景的视角，是征服者的视角。通篇无一字言志，而宇宙胸襟尽出，结句「歌以咏志」反而是多余的了。", "mood": "豪放", "famousLine": "星汉灿烂，若出其里", "poetName": "曹操"}, {"id": 26, "title": "龟虽寿", "subtitle": "", "poetId": 9, "dynasty": "魏晋", "genre": "四言乐府", "paragraphs": "神龟虽寿，犹有竟时。\n腾蛇乘雾，终为土灰。\n老骥伏枥，志在千里；\n烈士暮年，壮心不已。\n盈缩之期，不但在天；\n养怡之福，可得永年。\n幸甚至哉，歌以咏志。", "annotation": "竟：终结，终了。腾蛇：传说中乘雾飞行的神蛇。烈士：有远大抱负的人。盈缩：指寿命长短。养怡：保养身心。", "translation": "神龟虽然长寿，但终究有终结之时；腾蛇即使能乘雾飞天，死后也会化为土灰。年老的千里马虽然伏在马槽旁，雄心壮志仍是驰骋千里；有远大抱负的人士到了晚年，奋发思进的雄心不会止息。人的寿命长短，不只是由上天决定；只要保养身心，也可以延年益寿。真是幸运极了，用这首诗歌来表达自己的志向。", "appreciation": "时年五十三，「已矣哉」的年纪，他却写出了文学史上最昂扬的一首老之歌。先以神龟腾蛇说人终有一死，笔锋一转，正是这有限之身里，「老骥伏枥」四字迸出千钧之力——生命不以长度论，而以燃烧的程度论。这首诗式的乐观，比一切养生经都更能「可得永年」。", "mood": "哲理", "famousLine": "老骥伏枥，志在千里", "poetName": "曹操"}, {"id": 27, "title": "短歌行", "subtitle": "其一", "poetId": 9, "dynasty": "魏晋", "genre": "四言乐府", "paragraphs": "对酒当歌，人生几何！\n譬如朝露，去日苦多。\n慨当以慷，忧思难忘。\n何以解忧？唯有杜康。\n青青子衿，悠悠我心。\n但为君故，沉吟至今。\n呦呦鹿鸣，食野之苹。\n我有嘉宾，鼓瑟吹笙。\n明明如月，何时可掇？\n忧从中来，不可断绝。\n越陌度阡，枉用相存。\n契阔谈讌，心念旧恩。\n月明星稀，乌鹊南飞。\n绕树三匝，何枝可依？\n山不厌高，海不厌深。\n周公吐哺，天下归心。", "annotation": "几何：多少。杜康：相传最早酿酒的人，代指酒。子衿：周代学子的服装，代指贤才。掇：拾取，此为求而得之。讌：通「宴」。三匝：三圈。吐哺：吐出口中食物，指周公一顿饭三次吐哺起身接见贤士。", "translation": "一边喝酒一边高歌，人生的岁月有多少！好比晨露转瞬即逝，逝去的时光实在太多。席上歌声激昂慷慨，忧郁长久填满心窝。靠什么来排解忧闷？唯有狂饮方可解脱。穿青色衣领的学子，你们令我朝思暮想。只是因为你们的缘故，让我沉痛吟诵至今。阳光下鹿群呦呦欢鸣，悠然自得啃食绿坡。一旦四方贤才光临舍下，我将奏瑟吹笙宴请嘉宾。当空悬挂的皓月哟，何时才可以拾取；久蓄于心的忧愤哟，突然喷涌不可断绝。远方宾客踏着田间小路，一一屈驾前来探望我。久别重逢欢宴畅谈，争着将往日的情谊诉说。明月升起，星光闪烁，一群寻巢乌鹊向南飞去。绕树飞了三周却没敛翅，哪里才有它们栖身之所？高山不辞土石才见巍峨，大海不弃涓流方显壮阔。我愿如周公一般礼贤下士，愿天下的英杰真心归顺于我。", "appreciation": "「忧」之一字，贯穿全诗：忧人生短促，更忧贤才难得。他把自己写成一个立在暮色里的招贤者，用《诗经》里恋人的口吻思慕「青青子衿」——求贤求到了深情处。末尾忽然翻出吞吐天地的气象：山不厌高，海不厌深。英雄的孤独与英雄的抱负，在四言的旧瓶里酿出了建安最醇的一坛酒。", "mood": "豪放", "famousLine": "周公吐哺，天下归心", "poetName": "曹操"}, {"id": 28, "title": "蒿里行", "subtitle": "", "poetId": 9, "dynasty": "魏晋", "genre": "四言乐府", "paragraphs": "关东有义士，兴兵讨群凶。\n初期会盟津，乃心在咸阳。\n军合力不齐，踌躇而雁行。\n势利使人争，嗣还自相戕。\n淮南弟称号，刻玺于北方。\n铠甲生虮虱，万姓以死亡。\n白骨露于野，千里无鸡鸣。\n生民百遗一，念之断人肠。", "annotation": "义士：指讨伐董卓的关东州郡首领。盟津：周武王会盟诸侯伐纣之地，代指讨董联盟。雁行：大雁成行，喻讨董诸军观望不前。嗣还：其后。淮南弟称号：袁绍之弟袁术在淮南称帝。刻玺：袁绍谋废立、刻玉玺。", "translation": "关东的仗义之士都起兵讨伐凶残的董卓。当初约在盟津会师，心向汉室咸阳。可惜军合力不齐，踌躇观望如雁阵。势力利益使人相争，随后自相残杀。袁术在淮南称帝号，袁绍谋刻玉玺于北方。战士们的铠甲上都生了虮虱，百姓因此大量死亡。白骨暴露在荒野，千里之内听不见鸡鸣。活着的百姓百不剩一，念及此处令人肝肠寸断。", "appreciation": "这是一首「诗史」：讨董联盟如何从义举堕为内战，他一路亲历。最后四句没有任何修辞——白骨、荒野、无鸡鸣——白描到底，反而重逾千钧。史称曹操「倘使当年身便死，一生真伪有谁知」，可这首诗里的悲悯是装不出来的：他对乱世的痛，先于他对乱世的收拾。", "mood": "家国", "famousLine": "白骨露于野，千里无鸡鸣", "poetName": "曹操"}, {"id": 29, "title": "春晓", "subtitle": "", "poetId": 10, "dynasty": "唐", "genre": "五言绝句", "paragraphs": "春眠不觉晓，\n处处闻啼鸟。\n夜来风雨声，\n花落知多少。", "annotation": "晓：天刚亮。闻：听见。", "translation": "春天睡醒不觉天已大亮，到处是鸟儿清脆的叫声。回想昨夜的阵阵风雨声，不知吹落了多少娇美的春花。", "appreciation": "二十个字，全是听来的春天：醒来听鸟，忆夜听雨，还想听花落。不写所见只写所闻，春天反而漫无边际地铺开了。末句「知多少」轻轻一问，惜春而不伤春——隐者对光阴的态度，原来是这么温柔。", "mood": "闲适", "famousLine": "春眠不觉晓，处处闻啼鸟", "poetName": "孟浩然"}, {"id": 30, "title": "过故人庄", "subtitle": "", "poetId": 10, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "故人具鸡黍，邀我至田家。\n绿树村边合，青山郭外斜。\n开轩面场圃，把酒话桑麻。\n待到重阳日，还来就菊花。", "annotation": "具：准备，置办。鸡黍：农家待客的丰盛饭菜。合：环绕。轩：窗。场圃：打谷场和菜园。就：赴，欣赏。", "translation": "老朋友预备丰盛的饭菜，邀请我去他乡村田舍。翠绿的树林围绕着村落，苍青的山峦在城外横卧。推开窗户面对谷场菜园，手举酒杯闲谈庄稼情况。等到九九重阳节到来时，我还要来这里观赏菊花。", "appreciation": "一场最平常的田家饭，被写成了千古请柬。妙处全在不经意：不写情而情自浓——「待到重阳日，还来就菊花」，走的时候已经开始约下一顿。田园的可亲、故人的可交、盛唐农村的安稳，全在这句顺口而出的话里。", "mood": "田园", "famousLine": "待到重阳日，还来就菊花", "poetName": "孟浩然"}, {"id": 31, "title": "宿建德江", "subtitle": "", "poetId": 10, "dynasty": "唐", "genre": "五言绝句", "paragraphs": "移舟泊烟渚，\n日暮客愁新。\n野旷天低树，\n江清月近人。", "annotation": "烟渚：烟雾笼罩的小洲。客：旅人。旷：空阔。", "translation": "把船停泊在烟雾弥漫的沙洲旁，日落时分新愁又涌上了游子心头。原野空旷，远处的天空好像比树木还低；江水清澈，映照得月亮仿佛与人更亲近。", "appreciation": "「客愁新」三字是诗眼，却写得毫无愁相。野旷天低，是愁的空阔；江清月近，是愁的一点慰藉——天愈远，月愈近，孤独便有了着落。一句写尽羁旅，而不着一个苦字，这正是孟浩然「语淡味终不薄」的本色。", "mood": "思乡", "famousLine": "野旷天低树，江清月近人", "poetName": "孟浩然"}, {"id": 32, "title": "望洞庭湖赠张丞相", "subtitle": "", "poetId": 10, "dynasty": "唐", "genre": "五言律诗", "paragraphs": "八月湖水平，涵虚混太清。\n气蒸云梦泽，波撼岳阳城。\n欲济无舟楫，端居耻圣明。\n坐观垂钓者，徒有羡鱼情。", "annotation": "涵虚：水气与天空浑然一体。太清：天空。云梦泽：古代的大湖泽，涵盖今两湖之地。济：渡。端居：平居闲处。羡鱼情：用「临渊羡鱼，不如退而结网」之意。", "translation": "八月洞庭湖水暴涨几与岸平，水天一色交相辉映迷离难辨。云梦二泽水气蒸腾白白茫茫，波涛汹涌似乎把岳阳城撼动。想要渡水却没有船只，闲居不仕有愧于圣明天子。坐看垂钓之人多么悠闲，只能白白羡慕他人得鱼成功。", "appreciation": "一首干谒诗，却是千古写洞庭的第一等笔墨。「气蒸云梦泽，波撼岳阳城」十个字，把一座湖写出了宇宙的动静。后半自陈「欲济无舟楫」，求荐举而气不卑——先给你看海一样的湖，再说我的舟楫，气派先赢了。", "mood": "山水", "famousLine": "气蒸云梦泽，波撼岳阳城", "poetName": "孟浩然"}, {"id": 33, "title": "出塞", "subtitle": "其一", "poetId": 11, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "秦时明月汉时关，\n万里长征人未还。\n但使龙城飞将在，\n不教胡马度阴山。", "annotation": "但使：只要。龙城飞将：合用卫青奇袭龙城、李广善战之典，指英勇善战的名将。阴山：横亘今内蒙古，古代中原北境屏障。", "translation": "依旧是秦汉时期的明月和边关，守边御敌的将士们还没有回来。倘若龙城的飞将军李广如今还在，绝不让匈奴的兵马南下越过阴山。", "appreciation": "起句以「秦」「汉」二字把时间拉开千年——明月还是那轮明月，边关还是那道边关，而人未还。这种时空的苍茫，让后两句的呼吁成了千古一问：什么样的将军，才配得上这些等不到归期的士兵？所谓压卷之作，压在「人未还」三个字上。", "mood": "家国", "famousLine": "但使龙城飞将在，不教胡马度阴山", "poetName": "王昌龄"}, {"id": 34, "title": "芙蓉楼送辛渐", "subtitle": "", "poetId": 11, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "寒雨连江夜入吴，\n平明送客楚山孤。\n洛阳亲友如相问，\n一片冰心在玉壶。", "annotation": "平明：天刚亮。楚山：润州一带的山。冰心：像冰一样晶莹纯洁的心。玉壶：洁白的玉壶，喻高洁。", "translation": "冷雨连夜洒遍吴地江天，清晨送走你后，独自面对楚山离愁无限。到了洛阳，如果洛阳亲友问起我来，就请转告他们：我的心依然像玉壶里的冰那样晶莹纯洁。", "appreciation": "送别诗写到「孤」字便已动人，他偏要在孤山之外立起一件东西——玉壶冰心。被贬之人对亲友的交代，不是委屈也不是牢骚，而是一句品格的自证：你们问我近况，就说我没变。遭际愈狼狈，这一句愈清亮。", "mood": "送别", "famousLine": "洛阳亲友如相问，一片冰心在玉壶", "poetName": "王昌龄"}, {"id": 35, "title": "从军行", "subtitle": "其四", "poetId": 11, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "青海长云暗雪山，\n孤城遥望玉门关。\n黄沙百战穿金甲，\n不破楼兰终不还。", "annotation": "青海：青海湖。穿：磨穿，磨破。楼兰：西域古国，此代指侵扰西北的敌人。", "translation": "青海湖上乌云密布，连绵雪山一片黯淡。边塞古城，玉门雄关，远隔千里，遥遥相望。守边将士身经百战，铠甲都被磨穿，壮志不灭，不打败进犯之敌，誓不返回家乡。", "appreciation": "前两句把边关的苦寒与辽阔推到极致——暗、孤、遥，全是消极的意象；后两句却从这灰暗里拔地而起：金甲磨穿，人不还。终不还三字不是说狠话，是把「回不去」的宿命翻转为「不回去」的意志。盛唐的气象，全在这口气里。", "mood": "壮志", "famousLine": "黄沙百战穿金甲，不破楼兰终不还", "poetName": "王昌龄"}, {"id": 36, "title": "采莲曲", "subtitle": "其二", "poetId": 11, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "荷叶罗裙一色裁，\n芙蓉向脸两边开。\n乱入池中看不见，\n闻歌始觉有人来。", "annotation": "罗裙：丝罗织成的裙子。芙蓉：荷花。", "translation": "采莲少女的绿罗裙融入到田田荷叶中，仿佛一色，分不出彼此；少女的脸庞掩映在盛开的荷花间，相互照映。混入莲池中不见了踪影，听到歌声四起才觉察到有人前来。", "appreciation": "把人写没了，才见笔力。罗裙与荷叶一色，人面与荷花互映，少女整个融入了荷池——直到歌声响起，才恍然「有人」。不见时最美，一「觉」字唤醒全诗。这是唐诗里最干净的一场捉迷藏。", "mood": "闲适", "famousLine": "乱入池中看不见，闻歌始觉有人来", "poetName": "王昌龄"}, {"id": 37, "title": "锦瑟", "subtitle": "", "poetId": 12, "dynasty": "唐", "genre": "七言律诗", "paragraphs": "锦瑟无端五十弦，\n一弦一柱思华年。\n庄生晓梦迷蝴蝶，\n望帝春心托杜鹃。\n沧海月明珠有泪，\n蓝田日暖玉生烟。\n此情可待成追忆，\n只是当时已惘然。", "annotation": "无端：无缘由。五十弦：传说古瑟本五十弦。华年：美好的年华。庄生句：用庄周梦蝶典。望帝句：传说蜀王杜宇死后魂化杜鹃，啼声悲切。珠有泪：传说南海鲛人泣泪成珠。蓝田：产玉之山。", "translation": "瑟本有二十五根弦，但即使这样它的每一弦、每一音都足以表达我对那美好年华的思念。庄周其实知道自己只是向往那自由自在的蝴蝶；望帝那美好的心灵和作为可以感动杜鹃。大海里明月的影子是一颗颗眼泪化成的珍珠；蓝田山上阳光和暖，孕育美玉的烟霭依稀可见。那些美好的事和年代，只能留在回忆之中了；而当时那些人对待那些事的态度，我竟然已觉得惘然。", "appreciation": "一首人人爱却无人能解的诗。四个典故各自成谜，又如梦似幻地连成一气：梦、托、泪、烟，全是抓不住的东西。妙就妙在不必解——锦瑟三十弦也好五十弦也好，弹的就是「当时已惘然」五个字：身在福中时的迷惘，比追忆时的怅恨更无可奈何。", "mood": "怀人", "famousLine": "此情可待成追忆，只是当时已惘然", "poetName": "李商隐"}, {"id": 38, "title": "夜雨寄北", "subtitle": "", "poetId": 12, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "君问归期未有期，\n巴山夜雨涨秋池。\n何当共剪西窗烛，\n却话巴山夜雨时。", "annotation": "巴山：指大巴山，此泛指巴蜀之地。涨秋池：秋雨使池水上涨。何当：何时将要。剪烛：剪去烛花使烛更亮。", "translation": "你问我什么时候回去，我还没有确定的日子。此刻巴山的夜雨淅淅沥沥，涨满了秋天的池子。什么时候我们才能一起在西窗下剪烛夜谈，再回头说起今晚巴山夜雨中的思念呢？", "appreciation": "四句诗，两个「巴山夜雨」，两度时空对折：此刻的雨是孤独，他日烛下重说的雨，却是两人相视一笑的谈资。把眼前之苦预支为未来的甜，是深情者才有的自我安慰。可惜写此诗时王氏或已病故——这首寄北的诗，再也没有回信了。", "mood": "怀人", "famousLine": "何当共剪西窗烛，却话巴山夜雨时", "poetName": "李商隐"}, {"id": 39, "title": "无题", "subtitle": "相见时难", "poetId": 12, "dynasty": "唐", "genre": "七言律诗", "paragraphs": "相见时难别亦难，\n东风无力百花残。\n春蚕到死丝方尽，\n蜡炬成灰泪始干。\n晓镜但愁云鬓改，\n夜吟应觉月光寒。\n蓬山此去无多路，\n青鸟殷勤为探看。", "annotation": "丝：与「思」谐音双关。泪：烛泪，亦双关人之泪。晓镜：早晨照镜。云鬓：如云的鬓发。蓬山：蓬莱仙山，喻所思之人居处遥远。青鸟：神话中西王母的信使。", "translation": "见面的机会真是难得，分别时更是难舍难分，况且又兼东风将收的暮春天气，百花残谢，更加使人伤感。春蚕结茧到死时丝才吐完，蜡烛要燃尽成灰时像泪一样的蜡油才能滴干。女子早晨妆扮照镜，只担忧丰盛如云的鬓发改变颜色、青春的容颜消失；男子晚上长吟不寐，必然感到冷月侵人。对方的住处就在不远的蓬莱山，却无路可通，可望而不可及。希望有青鸟一样的使者殷勤地为我去探看亲人，来往传递消息。", "appreciation": "「别亦难」的第二个「难」，是难分难舍的难——首句十四个字便把两难写尽。颔联以春蚕、蜡炬作比，把自己的思念写到以生命为燃料的程度，遂成千古情语之绝唱。尾联忽然退一步求青鸟传信：明知无路，仍存一线想望。绝望处深情不灭，是义山与旁人的分别。", "mood": "怀人", "famousLine": "春蚕到死丝方尽，蜡炬成灰泪始干", "poetName": "李商隐"}, {"id": 40, "title": "登乐游原", "subtitle": "", "poetId": 12, "dynasty": "唐", "genre": "五言绝句", "paragraphs": "向晚意不适，\n驱车登古原。\n夕阳无限好，\n只是近黄昏。", "annotation": "向晚：傍晚。意不适：心情不舒畅。古原：乐游原，汉宣帝所立，地势高敞，为长安登览胜地。", "translation": "傍晚时心情不快，驾着车登上古原。夕阳啊无限美好，只不过接近黄昏。", "appreciation": "二十个字，一声长叹。为解「意不适」而登原，得到的却是更深的怅惘——夕阳越好，越照见无力挽回。关于「只是」二字历来有两解：惋惜「怎奈」，或转折「只因」；无论何解，那个把最美与将逝并置的瞬间，成了晚唐国运与诗人晚景共同的隐喻。", "mood": "悲秋", "famousLine": "夕阳无限好，只是近黄昏", "poetName": "李商隐"}, {"id": 41, "title": "山行", "subtitle": "", "poetId": 13, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "远上寒山石径斜，\n白云生处有人家。\n停车坐爱枫林晚，\n霜叶红于二月花。", "annotation": "石径：石头小路。坐：因为。霜叶：经霜的枫叶。", "translation": "沿着弯弯曲曲的小路上山，在那白云升起的地方，居然还有人家。停下车来，是因为喜爱这深秋枫林晚景。枫叶秋霜染过，艳比二月春花。", "appreciation": "深秋本该是萧瑟的题目，他却停了车。一个「爱」字翻案：经霜的枫叶红过二月春花——秋不是春的残余，是比春更烈的燃烧。杜牧的俊爽之气，连写景都带着这股昂首挺胸。", "mood": "山水", "famousLine": "停车坐爱枫林晚，霜叶红于二月花", "poetName": "杜牧"}, {"id": 42, "title": "清明", "subtitle": "", "poetId": 13, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "清明时节雨纷纷，\n路上行人欲断魂。\n借问酒家何处有？\n牧童遥指杏花村。", "annotation": "欲断魂：形容伤感极深，好像灵魂要与身体分开。借问：请问。杏花村：杏花深处的村庄。", "translation": "江南清明时节细雨纷纷飘洒，路上羁旅行人个个落魄断魂。借问当地之人何处买酒消愁？牧童笑而不答，遥指杏花深处的村庄。", "appreciation": "雨纷纷、欲断魂，愁绪已经写满，末句却忽然一笔荡开——牧童一指，画面里出现了杏花。愁没有解决，但酒有了方向，诗有了远方。全诗无一字说杏花之美，而千年读者都循着那个手指望去。这也是一问一答最古老的回答艺术。", "mood": "思乡", "famousLine": "借问酒家何处有？牧童遥指杏花村", "poetName": "杜牧"}, {"id": 43, "title": "泊秦淮", "subtitle": "", "poetId": 13, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "烟笼寒水月笼沙，\n夜泊秦淮近酒家。\n商女不知亡国恨，\n隔江犹唱后庭花。", "annotation": "笼：笼罩。秦淮：河名，流经金陵，两岸酒家繁华。商女：以卖唱为业的歌女。后庭花：陈后主所作《玉树后庭花》，后世视为亡国之音。", "translation": "浩渺寒江之上弥漫着迷蒙的烟雾，皓月的清辉洒在白色沙渚之上。入夜时分，我将小船停在秦淮河岸，临近酒家的地方。金陵歌女似乎不知何为亡国之恨、黍离之悲，竟依然在对岸吟唱着淫靡之曲《玉树后庭花》。", "appreciation": "两个「笼」字把烟、水、月、沙揉成一片朦胧，就在这片迷离里，歌声飘来。「不知」二字最重：商女何辜？唱的是听曲的人。晚唐的病不是歌女唱亡国之音，而是满座听客已经不会脸红。杜牧知兵而论政，四句绝句是一纸病危通知。", "mood": "家国", "famousLine": "商女不知亡国恨，隔江犹唱后庭花", "poetName": "杜牧"}, {"id": 44, "title": "赤壁", "subtitle": "", "poetId": 13, "dynasty": "唐", "genre": "七言绝句", "paragraphs": "折戟沉沙铁未销，\n自将磨洗认前朝。\n东风不与周郎便，\n铜雀春深锁二乔。", "annotation": "折戟：折断的戟。销：销蚀。将：拿起。周郎：周瑜。铜雀：铜雀台，曹操所建。二乔：大乔、小乔，分嫁孙策、周瑜。", "translation": "一支折断了的铁戟沉没在水底沙中还没有销蚀掉，经过自己又磨又洗，发现这是当年赤壁之战的遗留之物。假如东风不给周瑜以方便，结局恐怕是曹操取胜，二乔被关进铜雀台了。", "appreciation": "从沙里一支断戟起兴，把一场决定百年国运的大战，缩进「铜雀春深锁二乔」的假设里。以两位女子的命运代言江山的易主，举重若轻，是绝句中最高级的写法。他其实在说自己的怀才不遇：东风不与杜郎便。", "mood": "哲理", "famousLine": "东风不与周郎便，铜雀春深锁二乔", "poetName": "杜牧"}, {"id": 45, "title": "雨霖铃", "subtitle": "寒蝉凄切", "poetId": 14, "dynasty": "宋", "genre": "词", "paragraphs": "寒蝉凄切，对长亭晚，骤雨初歇。\n都门帐饮无绪，留恋处，兰舟催发。\n执手相看泪眼，竟无语凝噎。\n念去去，千里烟波，暮霭沉沉楚天阔。\n\n多情自古伤离别，更那堪，冷落清秋节！\n今宵酒醒何处？杨柳岸，晓风残月。\n此去经年，应是良辰好景虚设。\n便纵有千种风情，更与何人说？", "annotation": "长亭：古人送别之处。都门：京城门外。兰舟：船的美称。凝噎：喉咙哽塞说不出话。楚天：南方天空。经年：年复一年。风情：深情密意。", "translation": "秋后的知了叫得那样凄凉，面对着长亭，正是傍晚时分，一阵急雨刚停。在京都城外设帐饯别，却没有畅饮的心绪，正在依依不舍之时，船上的人已催着出发。握着手互相瞧着，满眼泪花，直到最后也无言相对，千言万语都噎在喉间说不出来。想到这回去南方，这一程又一程，千里烟波，雾霭沉沉，楚地的天空竟是一望无际的辽阔。自古以来多情的人最伤离别，更何况，又逢这冷落萧瑟的秋季！这离愁哪能经受得了！谁知我今夜酒醒时身在何处？怕是只有杨柳岸边，面对凄厉的晨风和黎明的残月了。这一去长年相别，相爱的人不在一起，我料想即使遇到好天气、好风景，也如同虚设。即使有满腹的情意，又能同谁一同诉说呢？", "appreciation": "离别词的巅峰。上片写别时之难——「执手相看泪眼」定格了千年的送别；下片忽然宕开，替未来想象：今宵酒醒，杨柳岸晓风残月。最痛的不是离别那一刻，而是想到离别之后的无数个时刻。词到柳永手中，第一次有了电影般的时空调度。", "mood": "送别", "famousLine": "今宵酒醒何处？杨柳岸，晓风残月", "poetName": "柳永"}, {"id": 46, "title": "望海潮", "subtitle": "东南形胜", "poetId": 14, "dynasty": "宋", "genre": "词", "paragraphs": "东南形胜，三吴都会，钱塘自古繁华。\n烟柳画桥，风帘翠幕，参差十万人家。\n云树绕堤沙，怒涛卷霜雪，天堑无涯。\n市列珠玑，户盈罗绮，竞豪奢。\n\n重湖叠巘清嘉，有三秋桂子，十里荷花。\n羌管弄晴，菱歌泛夜，嬉嬉钓叟莲娃。\n千骑拥高牙，乘醉听箫鼓，吟赏烟霞。\n异日图将好景，归去凤池夸。", "annotation": "形胜：地理形势重要优越之处。三吴：泛指江南吴地。天堑：天然壕沟，指钱塘江。重湖：西湖以白堤分为里湖外湖。叠巘：重叠的山峰。高牙：高扬的牙旗，指大官仪仗。凤池：凤凰池，代指中书省。", "translation": "地处东南，地理位置优越，是三吴的都会，钱塘从古以来就十分繁华。如烟的柳树、彩绘的桥梁，挡风的帘子、翠绿的帐幕，楼阁高高低低，大约有十万户人家。高耸入云的大树环绕着沙堤，汹涌的浪涛卷起如霜雪般的白浪，钱塘江是天堑一望无涯。市场上陈列着珠玉珍宝，家家户户都满是绫罗绸缎，竞相奢华。里湖、外湖与重重叠叠的山岭清秀美好，有秋天的桂子，十里的荷花。晴天欢奏羌笛，夜晚采菱唱歌，钓鱼的老翁、采莲的姑娘都嬉笑颜开。千名骑兵簇拥着长官乘醉听吹箫击鼓，观赏吟咏云霞烟景。他日把这美好的景致画出来，回京升官时向人们夸耀。", "appreciation": "一首写给杭州的「城市宣传诗」，却写出了一座城的一生：上有怒涛天堑，下有三秋桂子。据说金主完颜亮读到「三秋桂子，十里荷花」，遂起投鞭渡江之志——一篇词章引发一场战争虽属传说，却道尽这四十六字的诱惑力。市井、湖山、笙歌、千骑，北宋的盛世自信，全在柳永的慢词里。", "mood": "山水", "famousLine": "三秋桂子，十里荷花", "poetName": "柳永"}, {"id": 47, "title": "蝶恋花", "subtitle": "伫倚危楼风细细", "poetId": 14, "dynasty": "宋", "genre": "词", "paragraphs": "伫倚危楼风细细，\n望极春愁，\n黯黯生天际。\n草色烟光残照里，\n无言谁会凭阑意。\n\n拟把疏狂图一醉，\n对酒当歌，\n强乐还无味。\n衣带渐宽终不悔，\n为伊消得人憔悴。", "annotation": "伫倚：久倚。危楼：高楼。黯黯：心情沮丧。会：理解。拟把：打算。疏狂：狂放不羁。伊：她。", "translation": "久久地倚靠着高楼的栏杆，微风丝丝细细，极目远望，春愁从天边黯然升起。青青草色、迷蒙烟光在夕阳残照里，默默无言，又有谁能理解凭栏的心意？打算借放浪形骸来求得一醉，对着美酒纵情高歌，强颜欢笑终究没有滋味。衣带渐宽也始终不后悔，为了她值得我形容憔悴。", "appreciation": "词牌是蝶恋花，写的却是「无言谁会凭阑意」的孤独。结拍突然从满纸黯淡里迸出一句决绝的誓言——衣带渐宽终不悔。王国维借它喻治学成大事业、大学问的第二境界：为所爱者，瘦损何妨。一句情语能升华成人生境界，因为它写的本就不是情，是痴。", "mood": "怀人", "famousLine": "衣带渐宽终不悔，为伊消得人憔悴", "poetName": "柳永"}, {"id": 48, "title": "八声甘州", "subtitle": "对潇潇暮雨洒江天", "poetId": 14, "dynasty": "宋", "genre": "词", "paragraphs": "对潇潇暮雨洒江天，一番洗清秋。\n渐霜风凄紧，关河冷落，残照当楼。\n是处红衰翠减，苒苒物华休。\n惟有长江水，无语东流。\n\n不忍登高临远，望故乡渺邈，归思难收。\n叹年来踪迹，何事苦淹留。\n想佳人妆楼颙望，误几回、天际识归舟。\n争知我，倚阑干处，正恁凝愁！", "annotation": "潇潇：雨势急骤。关河：山河关隘。是处：到处。苒苒：渐渐。颙望：抬头凝望。争知：怎知。恁：如此。", "translation": "面对着潇潇暮雨从天上洒落江天，经过一番洗刷，秋色分外清朗。渐渐感到凄清的霜风一阵紧似一阵，山川关河一片冷落，夕阳余晖斜照楼头。到处是花残叶凋，美好的景物渐渐地衰竭。只有长江之水，无声无息地向东流淌。不忍心登高远望，故乡遥远渺茫，归乡的心思难以收拢。叹息这些年的行踪，为什么苦苦地长久滞留？想象佳人也正在妆楼上抬头远望，多少次错把远处驶来的船当作心上人的归舟。她哪知道我这里，倚着栏杆，也正是这样愁绪凝结！", "appreciation": "苏轼激赏「霜风凄紧，关河冷落，残照当楼」，说此语「不减唐人高处」。妙在结拍的双向想象：我望故乡而思佳人，佳人妆楼误识归舟——她不知道我，我也不知道她错认了几回船。两地相思隔着一道天际互相打听，词的空间从此有了纵深。", "mood": "思乡", "famousLine": "望故乡渺邈，归思难收", "poetName": "柳永"}, {"id": 49, "title": "生查子", "subtitle": "元夕", "poetId": 15, "dynasty": "宋", "genre": "词", "paragraphs": "去年元夜时，花市灯如昼。\n月上柳梢头，人约黄昏后。\n\n今年元夜时，月与灯依旧。\n不见去年人，泪湿春衫袖。", "annotation": "元夜：元宵节之夜。花市：灯市。春衫：年轻人所穿衣衫。", "translation": "去年正月十五元宵节，花市灯光亮如白昼。明月升上柳树梢头，恋人相约黄昏之后。今年正月十五元宵节，月光与灯光依旧。却见不到去年的那人，相思的泪水打湿了春衫袖子。", "appreciation": "两段几乎相同的句子，只换了八个字，就把一场爱情从巅峰写到终点。「月与灯依旧」五字最狠：景物全在，独缺一人。词的真假尚有争论（一说朱淑真作），但「月上柳梢头」这六个字，已经替所有中国人规定了元宵节的浪漫。", "mood": "怀人", "famousLine": "月上柳梢头，人约黄昏后", "poetName": "欧阳修"}, {"id": 50, "title": "采桑子", "subtitle": "轻舟短棹西湖好", "poetId": 15, "dynasty": "宋", "genre": "词", "paragraphs": "轻舟短棹西湖好，\n绿水逶迤，\n芳草长堤，\n隐隐笙歌处处随。\n\n无风水面琉璃滑，\n不觉船移，\n微动涟漪，\n惊起沙禽掠岸飞。", "annotation": "短棹：小桨。西湖：指颍州西湖。逶迤：曲折绵延。琉璃：形容水面光滑如玻璃。沙禽：沙洲上的水鸟。", "translation": "轻便的小船划着短桨，颍州西湖风光真好。碧绿的湖水蜿蜒流淌，长堤上芳草青青，隐约传来笙歌，处处相随。无风的水面光滑如琉璃，感觉不到船在移动，只见微微荡起的涟漪，惊起水鸟掠过湖岸飞去。", "appreciation": "退休老人的西湖春游，写得像少年人的初遇。全词最静也最动：「不觉船移」是静，涟漪惊禽是动——一动只为了照见静。没有一句感慨，没有一个典故，六十一岁的六一居士把词写回了天赋本身。", "mood": "闲适", "famousLine": "无风水面琉璃滑，不觉船移", "poetName": "欧阳修"}, {"id": 51, "title": "蝶恋花", "subtitle": "庭院深深深几许", "poetId": 15, "dynasty": "宋", "genre": "词", "paragraphs": "庭院深深深几许，\n杨柳堆烟，\n帘幕无重数。\n玉勒雕鞍游冶处，\n楼高不见章台路。\n\n雨横风狂三月暮，\n门掩黄昏，\n无计留春住。\n泪眼问花花不语，\n乱红飞过秋千去。", "annotation": "几许：多少。堆烟：杨柳浓密如烟雾笼罩。玉勒雕鞍：镶玉的马笼头、雕花的马鞍，代指华贵的车马。章台：汉代长安街名，代指歌楼妓馆。雨横：雨势猛烈。乱红：落花。", "translation": "庭院深深，不知道到底有多深？杨柳如烟，密密层层，帘幕不计其数。如今丈夫乘着华贵的车马到歌楼妓馆游冶去了，我登上高楼也望不见他去的章台路。暮春三月，风雨交加；掩起黄昏中的门，也无法把春天留住。含泪询问落花，落花默默无言，纷纷乱乱地飞过秋千而去。", "appreciation": "「深」字三叠，一开场就设下迷阵——深几许？问了无人答，只有帘幕无重数。到结拍才见真章：泪眼问花，花不语，反而乱红飞过秋千去。问花本是痴，花的沉默与飞走是双倍的残忍。李清照酷爱此词，「爱其语新意深」，把它化进了自己的「庭院深深」式审美。", "mood": "怀人", "famousLine": "泪眼问花花不语，乱红飞过秋千去", "poetName": "欧阳修"}, {"id": 52, "title": "戏答元珍", "subtitle": "", "poetId": 15, "dynasty": "宋", "genre": "七言律诗", "paragraphs": "春风疑不到天涯，\n二月山城未见花。\n残雪压枝犹有橘，\n冻雷惊笋欲抽芽。\n夜闻归雁生乡思，\n病入新年感物华。\n曾是洛阳花下客，\n野芳虽晚不须嗟。", "annotation": "元珍：丁宝臣，字元珍，时任峡州判官。天涯：极远之地，指夷陵。山城：指夷陵。冻雷：早春的雷。物华：美好的景物。嗟：叹息。", "translation": "我怀疑春风吹不到这边远的山城，已是二月，居然还看不到一朵花。残雪压着枝条，树杈上尚留着去年的橘子；早春的雷声惊动竹笋，想要抽出新芽。夜晚听到归雁的啼声，思念起遥远的家乡；带着病进入新年，面对眼前景物感慨万千。我曾在洛阳的名花丛中做客，这山野的花虽然开得晚，也不必叹息。", "appreciation": "贬谪诗最容易写成苦情戏，他偏在颔联埋下生趣：残雪之下犹有橘，冻雷声中笋欲芽——被压着的东西都在准备生长。尾联以「洛阳花下客」自傲：见过牡丹盛世的人，等得起野花晚开。欧阳修的旷达不是天性，是从这首诗开始练出来的。", "mood": "悲秋", "famousLine": "曾是洛阳花下客，野芳虽晚不须嗟", "poetName": "欧阳修"}, {"id": 53, "title": "泊船瓜洲", "subtitle": "", "poetId": 16, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "京口瓜洲一水间，\n钟山只隔数重山。\n春风又绿江南岸，\n明月何时照我还。", "annotation": "京口：今江苏镇江，与瓜洲隔江相望。一水：指长江。钟山：今南京紫金山。", "translation": "京口和瓜洲之间只隔着一条长江，钟山就隐没在几座山峦的后面。和煦的春风又吹绿了大江南岸，明月什么时候才能照着我回到钟山下的家里？", "appreciation": "「绿」字是炼字史上最著名的公案：洪迈《容斋随笔》记他先后用过「到」「过」「入」「满」，改了十几次才定为「绿」——形容词作动词，春风便有了手。第三句写尽盼归之意，第四句却在问句里悬着：变法中人，归期由不得自己。", "mood": "思乡", "famousLine": "春风又绿江南岸，明月何时照我还", "poetName": "王安石"}, {"id": 54, "title": "梅花", "subtitle": "", "poetId": 16, "dynasty": "宋", "genre": "五言绝句", "paragraphs": "墙角数枝梅，\n凌寒独自开。\n遥知不是雪，\n为有暗香来。", "annotation": "凌寒：冒着严寒。遥：远远地。为：因为。暗香：幽幽的香气。", "translation": "墙角有几枝梅花，正冒着严寒独自盛开。远远地就知道洁白的梅花不是雪，因为有一阵阵幽香隐隐飘来。", "appreciation": "写在变法失败、两度罢相之后，二十个字全是自况：墙角是冷落的处境，凌寒是逆境，独自开是不改其志。末二句最妙——远远望去像雪，正因不是雪（有暗香），才值得辨认真假。世上有的是雪一样白的从众，只有香气证明你是梅。", "mood": "哲理", "famousLine": "遥知不是雪，为有暗香来", "poetName": "王安石"}, {"id": 55, "title": "登飞来峰", "subtitle": "", "poetId": 16, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "飞来山上千寻塔，\n闻说鸡鸣见日升。\n不畏浮云遮望眼，\n自缘身在最高层。", "annotation": "飞来峰：在越州（今绍兴）宝林山。千寻：极言其高，八尺为寻。闻说：听说。浮云：浮云蔽日喻奸邪障蔽贤良。自缘：自然因为。", "translation": "登上飞来峰顶高耸入云的塔，听说鸡鸣时分就可以看到旭日东升。不怕浮云会遮住我的视线，只因为如今我身在最高层。", "appreciation": "三十岁的王安石途经越州写下此诗，正涉世未深，却已有了俯视浮云的气概。与王之涣「更上一层楼」、苏轼「不识庐山真面目」并读最有趣：三人都在解同一道题——位置决定眼界。他的答案是进取型的：只要站得够高，浮云算什么。", "mood": "哲理", "famousLine": "不畏浮云遮望眼，自缘身在最高层", "poetName": "王安石"}, {"id": 56, "title": "元日", "subtitle": "", "poetId": 16, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "爆竹声中一岁除，\n春风送暖入屠苏。\n千门万户曈曈日，\n总把新桃换旧符。", "annotation": "屠苏：屠苏酒，元日习俗饮之以避瘟。曈曈：日出光亮的样子。桃符：画有神荼郁垒二神的桃木板，新年悬于门旁以辟邪。", "translation": "阵阵轰鸣的爆竹声中，旧的一年过去了；和暖的春风吹来了新年，人们欢乐地畅饮着屠苏酒。初升的太阳照耀着千家万户，他们都忙着取下旧桃符，换上新桃符。", "appreciation": "写于拜相推行新法的熙宁二年正月——这哪里是写过年，是写他自己迎来的时代。「新桃换旧符」五字，把一场大变法缩进了最寻常的年俗里：除旧布新，本是人间常理。喜庆底下藏着雷霆，是此诗千年后被反复引用的原因。", "mood": "闲适", "famousLine": "千门万户曈曈日，总把新桃换旧符", "poetName": "王安石"}, {"id": 57, "title": "游山西村", "subtitle": "", "poetId": 17, "dynasty": "宋", "genre": "七言律诗", "paragraphs": "莫笑农家腊酒浑，\n丰年留客足鸡豚。\n山重水复疑无路，\n柳暗花明又一村。\n箫鼓追随春社近，\n衣冠简朴古风存。\n从今若许闲乘月，\n拄杖无时夜叩门。", "annotation": "腊酒：腊月酿的酒。豚：小猪，代指猪肉。春社：立春后第五个戊日祭祀土地神以祈丰年。闲乘月：趁着月色闲游。无时：随时。", "translation": "不要笑话农家腊月酿的酒浑浊，丰收之年他们待客的菜肴极为丰盛。山峦重叠水流曲折，正担心无路可走时，柳绿花艳眼前豁然又出现一个山村。吹箫击鼓的队伍渐渐临近，春社祭祀的日子快到了；村民衣冠简朴，古代风气仍然保存。今后如果还能趁大好月色出外闲游，我一定拄着拐杖随时来敲你的家门。", "appreciation": "罢官归乡的第一年，他在农家饭桌上写下了人生最著名的一句哲学：「山重水复疑无路，柳暗花明又一村」。本是山道实景，却从此成为中国人对付绝境的通用解药。尾联的拄杖夜叩门与首句的莫笑相呼应——这顿饭，他打算一直吃下去。", "mood": "田园", "famousLine": "山重水复疑无路，柳暗花明又一村", "poetName": "陆游"}, {"id": 58, "title": "示儿", "subtitle": "", "poetId": 17, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "死去元知万事空，\n但悲不见九州同。\n王师北定中原日，\n家祭无忘告乃翁。", "annotation": "元：本来。九州同：全国统一。王师：朝廷的军队。乃翁：你们的父亲。", "translation": "本来就知道人死去了就什么也没有了，只是为没有亲眼看到祖国的统一而感到悲伤。朝廷的军队收复中原领土的那一天，在家中祭祀祖先的时候，千万不要忘记把这件事情告诉你们的父亲。", "appreciation": "一首绝笔诗，也是一份遗嘱，更是一个八十五岁老人一生的总结案陈词。明知死去万事空，偏偏放不下一件与己无关的事。七百年后王师仍未北定时，后人读此诗无不鼻酸——诗里的等待，成了民族记忆里最长的一次等待。", "mood": "家国", "famousLine": "王师北定中原日，家祭无忘告乃翁", "poetName": "陆游"}, {"id": 59, "title": "十一月四日风雨大作", "subtitle": "其二", "poetId": 17, "dynasty": "宋", "genre": "七言绝句", "paragraphs": "僵卧孤村不自哀，\n尚思为国戍轮台。\n夜阑卧听风吹雨，\n铁马冰河入梦来。", "annotation": "僵卧：直挺挺躺着，形容老病。戍：守卫。轮台：在今新疆，汉代边防重地，代指边关。夜阑：夜深。", "translation": "我直挺挺躺在孤寂荒凉的乡村里，没有为自己的处境而感到悲哀，心中还想着替国家戍守边疆。夜深了，我躺在床上听到那风雨的声音，迷迷糊糊地梦见自己骑着披甲的战马跨过冰封的河流出征北方疆场。", "appreciation": "六十八岁，罢官家居，一场大雨夜。前两句是白描的老病，后两句忽然天马行空——风雨声进了梦，梦成了铁马冰河。现实愈局促，梦境愈辽阔，这一梦替他守住了壮志的最后一寸疆土。孤村与轮台之间，隔的不是山川，是二十年的不被任用。", "mood": "壮志", "famousLine": "夜阑卧听风吹雨，铁马冰河入梦来", "poetName": "陆游"}, {"id": 60, "title": "钗头凤", "subtitle": "红酥手", "poetId": 17, "dynasty": "宋", "genre": "词", "paragraphs": "红酥手，黄縢酒，满城春色宫墙柳。\n东风恶，欢情薄。\n一怀愁绪，几年离索。\n错、错、错。\n\n春如旧，人空瘦，泪痕红浥鲛绡透。\n桃花落，闲池阁。\n山盟虽在，锦书难托。\n莫、莫、莫！", "annotation": "黄縢酒：官酒以黄纸封口。离索：离群索居。浥：湿润。鲛绡：传说鲛人所织薄纱，代指手帕。锦书：书信。", "translation": "你红润酥腻的手里，捧着盛上黄縢酒的杯子。满城荡漾着春天的景色，你却早已像宫墙中的绿柳那般遥不可及。春风多么可恶，把浓郁的欢情吹得那样稀薄。满杯酒像一杯忧愁的情绪，离别这几年的生活十分萧索。遥想当初，错、错、错！美丽的春景依然如旧，只是人却白白相思地消瘦。泪水洗尽脸上的胭脂，又把薄绸的手帕全都湿透。满春的桃花凋落在寂静空旷的池塘楼阁上。永远相爱的誓言还在，可是锦文书信再也难以交付。遥想当初，莫、莫、莫！", "appreciation": "绍兴二十五年春，三十一岁的陆游游沈园，遇已为他人妻的前妻唐琬，题此词于壁。三个「错」字与三个「莫」字，上下阕各六字，是词史上最沉重的十二个字。相传唐琬和词一阕「人成各，今非昨」，不久郁郁而终；陆游此后一生重游沈园，七十五岁犹写「伤心桥下春波绿，曾是惊鸿照影来」。一阕词，用了他一生来注脚。", "mood": "怀人", "famousLine": "山盟虽在，锦书难托", "poetName": "陆游"}];
